INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1632', 'spa', 'Derramar, verter — verter líquido, sangre o el Espíritu; figuradamente, abandonarse temerariamente.', 'Derramar, verter — verter líquido, sangre o el Espíritu; figuradamente, abandonarse temerariamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1633', 'spa', 'partir, retirarse, salir; irse de un lugar o situacion', 'Este verbo significa partir o retirarse de un lugar. En Lucas 21:21, Jesus advierte que los que esten en Judea huyan a las montanas, y los que esten en la ciudad "salgan" cuando vean a Jerusalen rodeada de ejercitos. El verbo enfatiza la accion de irse, evacuar, abandonar el lugar. En el uso clasico incluye emigrar o retirarse de un sitio. Las traducciones multilingues (salgan, sortir) captan el sentido de salir o marcharse, subrayando la urgencia de la huida en la advertencia apocaliptica de Jesus.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1634', 'spa', 'Exhalar el alma, expirar, morir súbitamente; término enfático para una muerte repentina o dramática', 'El verbo ἐκψύχω (ἐκ + ψύχω «enfriar», emparentado con ψυχή «alma/aliento») significa perder el conocimiento, desvanecerse o expirar, con la connotación de que el aliento o el alma abandona el cuerpo. Hechos lo emplea para muertes súbitas y dramáticas: Ananías y Safira fulminados por mentir al Espíritu Santo, y Herodes Agripa devorado por gusanos bajo juicio divino. La palabra no sugiere un fallecimiento apacible, sino un cese abrupto y a menudo violento de la vida: el alma o aliento arrancado de golpe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1635', 'spa', 'voluntariamente, de buena gana, por propia voluntad', 'Este adverbio significa voluntariamente o por libre voluntad, enfatizando la elección voluntaria. Romanos 8:20 lo usa al describir cómo la creación fue sujetada a vanidad no voluntariamente sino por la voluntad de Dios, y 1 Corintios 9:17 contrasta el servicio voluntario con el involuntario. La palabra subraya la decisión intencional y libre en lugar de la compulsión. El uso clásico distinguía entre actos voluntarios e involuntarios, una distinción ética y legal fundamental.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1636', 'spa', 'Olivo: como topónimo en ''Monte de los Olivos''; la planta viva empleada en la alegoría de Pablo; el fruto de la aceituna. El sustantivo griego ἐλαία de', 'Olivo: como topónimo en ''Monte de los Olivos''; la planta viva empleada en la alegoría de Pablo; el fruto de la aceituna. El sustantivo griego ἐλαία designa el olivo en todas sus formas — árbol, olivar y fruto — y en el Nuevo Testamento aparece mayoritariamente como parte del topónimo ''Monte de los Olivos'' (τὸ Ὄρος τῶν Ἐλαιῶν). Once de sus quince apariciones fijan este lugar emblemático en la narrativa evangélica: Jesús enseña a sus discípulos allí con vista a Jerusalén (Mt 24:3; Mc 13:3), se retira la noche de su arresto (Mt 26:30; Lc 22:39) y asciende desde su cima (Hch 1:12). Más allá de la geografía, Pablo transforma el olivo en una de las metáforas botánicas más desarrolladas del NT: el olivo cultivado representa a Israel, las ramas silvestres a los creyentes gentiles injertados ''contra naturaleza'' (Ro 11:17, 24), y la raíz que sostiene a ambos es la fidelidad de Dios a su pacto. Apocalipsis 11:4 identifica a los dos testigos como ''dos olivos'', evocando la visión del candelabro de Zacarías. Finalmente, Santiago 3:12 aísla el fruto: ''¿Acaso puede la higuera producir aceitunas?'' — una apelación retórica al orden natural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1637', 'spa', 'Aceite de oliva — aceite prensado de aceitunas, usado para ungir, lámparas, sanación y comercio. El sustantivo ἔλαιον (elaion) designa el aceite de ol', 'Aceite de oliva — aceite prensado de aceitunas, usado para ungir, lámparas, sanación y comercio. El sustantivo ἔλαιον (elaion) designa el aceite de oliva, el aceite esencial del antiguo Mediterráneo. En la parábola de las diez vírgenes, cinco insensatas carecen de aceite para sus lámparas (Mt 25:3-4, 8). Jesús señala que Simón ''no ungió mi cabeza con aceite'' (Lc 7:46). Los Doce ungen a los enfermos con aceite (Mr 6:13), y Santiago instruye a los ancianos a hacer lo mismo (Stg 5:14). El buen samaritano vierte aceite y vino sobre las heridas (Lc 10:34). En Apocalipsis, el aceite es un producto protegido (Ap 6:6) y un lujo de Babilonia (Ap 18:13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1638', 'spa', 'olivar, huerto de olivos; especificamente, el Monte de los Olivos cerca de Jerusalen', 'Este sustantivo designa un olivar o huerto de olivos, y en el Nuevo Testamento se refiere especificamente al Monte de los Olivos, la cadena de colinas al este de Jerusalen. En Hechos 1:12, los discipulos regresan a Jerusalen desde "el monte llamado del Olivar" tras la ascension de Jesus. Este lugar fue significativo en el ministerio de Jesus: enseno alli, oro en Getsemani en su ladera y ascendio desde su cima. El nombre conserva el caracter agricola del sitio, una colina plantada de olivos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1639', 'spa', 'elamitas; habitantes de Elam, region al este de Mesopotamia (actual suroeste de Iran)', 'Esta designacion etnica se refiere a los elamitas, pueblo de Elam, un antiguo reino al este de Babilonia en lo que hoy es el suroeste de Iran. En Hechos 2:9, los elamitas figuran entre los peregrinos judios presentes en Jerusalen durante Pentecostes que escuchan a los apostoles hablar en lenguas. Su presencia subraya la amplitud de la diaspora judia y el alcance internacional del milagro de Pentecostes. Elam fue una civilizacion antigua importante, y las comunidades judias existian alli desde el exilio babilonico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1640', 'spa', 'Menor, inferior, más pequeño; más joven o de rango o grado inferior', 'Forma comparativa de μικρός (a través de ἐλαχύς), este adjetivo expresa ''menor'' en múltiples dimensiones: tamaño, edad, rango o calidad. En las bodas de Caná, el maestresala observa que el vino inferior normalmente se sirve al final (Jn 2:10). Pablo cita el oráculo sobre Jacob y Esaú: ''el mayor servirá al menor'' (Ro 9:12). El principio de que ''sin discusión alguna, el menor es bendecido por el mayor'' articula el argumento sobre Melquisedec en Hebreos 7:7. En español, ''menor'' e ''inferior'' distinguen con claridad el grado del tamaño.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1641', 'spa', 'tener menos, carecer; recibir o poseer una cantidad menor, quedarse corto', 'Este verbo significa tener menos, carecer o quedarse corto en cantidad. En 2 Corintios 8:15, Pablo cita Éxodo 16:18 respecto al maná: "El que recogió mucho no tuvo de más, y el que recogió poco no tuvo de menos." El verbo describe el milagro de la suficiencia: quienes recogieron menos no se encontraron en carencia. Este principio ilustra la igualdad y el cuidado mutuo que Pablo promueve en la generosidad cristiana: los recursos compartidos de manera que nadie quede en necesidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1642', 'spa', 'Hacer menor, disminuir, reducir; mengua en tamaño, rango o prominencia', 'El verbo ἐλασσόω (de ἐλάσσων «menor») significa hacer más pequeño, reducir o disminuir. Su uso bíblico abarca desde la disminución voluntaria de la prominencia de Juan el Bautista hasta el rebajamiento temporal de Cristo por debajo de los ángeles en la encarnación. El término no denota una pérdida accidental, sino una reducción deliberada o decretada: hacer que algo o alguien sea menos de lo que era o podría ser, ya sea por autoabnegación o por designio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1643', 'spa', 'Impulsar, propulsar o remar; referido al viento o una fuerza que empuja embarcaciones, personas u objetos.', 'Verbo versátil de movimiento enérgico —impulsar, remar o propulsar— usado tanto en contextos náuticos como figurados. Los discípulos se esfuerzan remando contra un viento contrario (Mc 6:48; Jn 6:19), un endemoniado es impulsado por el espíritu inmundo hacia lugares desiertos (Lc 8:29), las naves son dirigidas por sus pilotos (Stg 3:4), y los falsos maestros son comparados con nubes sin agua «arrastradas» por los vientos (2 P 2:17). El énfasis recae en la fuerza externa que mueve al sujeto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1644', 'spa', 'ligereza, levedad; inconstancia o falta de seriedad en el juicio o compromiso', 'Este sustantivo puede significar ligereza física o, en sentido figurado, levedad o inconstancia. En 2 Corintios 1:17, Pablo se defiende de la acusación de actuar con ligereza, es decir, de hacer planes de manera descuidada o caprichosa. Pregunta retóricamente si acaso tomó sus decisiones según la carne, mostrando inconstancia al decir "sí, sí" y "no, no" al mismo tiempo. El término implica falta de seriedad o fiabilidad. En el uso clásico incluye ligereza de peso o, en sentido moral, frivolidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1645', 'spa', 'ligero, liviano, fácil de llevar, no pesado', 'Este adjetivo significa ligero en peso o fácil de llevar. Jesús lo usa en Mateo 11:30 al declarar que su carga es ligera, y Pablo lo aplica en 2 Corintios 4:17 para describir la aflicción presente como ''leve'' en comparación con la gloria eterna. La palabra contrasta con ''pesado'' o ''gravoso''. El uso clásico abarcaba desde la ligereza física literal hasta la facilidad metafórica. Los epitafios antiguos lo usaban en la frase ''que la tierra te sea leve''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1646', 'spa', 'mínimo, el más pequeño, muy pequeño — adjetivo superlativo que indica el grado más bajo en tamaño, rango o importancia. Ἐλάχιστος es el superlativo de', 'mínimo, el más pequeño, muy pequeño — adjetivo superlativo que indica el grado más bajo en tamaño, rango o importancia. Ἐλάχιστος es el superlativo de ἐλαχύς (''pequeño''), y funciona como opuesto de μέγιστος (''el mayor''). En sus 13 apariciones neotestamentarias describe lo más pequeño o menos significativo en diversas dimensiones: rango en el reino (Mt 5:19, 11:11, Lc 7:28), insignificancia aparente de un lugar (Mt 2:6 ''Belén, de ningún modo la menor''), los asuntos aparentemente triviales de la vida cotidiana (Lc 12:26, 16:10, 19:17) y los miembros olvidados de la familia humana (Mt 25:40, 45 ''uno de estos mis hermanos más pequeños''). Jesús invierte característicamente la jerarquía esperada, declarando que la fidelidad en lo mínimo revela la aptitud para lo máximo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1647', 'spa', 'el menor, el más pequeño, el más insignificante; forma superlativa que denota grado o estatus mínimo', 'Esta es la forma superlativa que significa "el menor" o "el más pequeño", usada frecuentemente para indicar mínima importancia o estatus. En Efesios 3:8, Pablo se llama a sí mismo "el más pequeño de todos los santos", una descripción humilde que resalta su modestia. La forma comparativa aquí intensifica el superlativo: menos que el menor. El término puede referirse a tamaño, tiempo, número o importancia. El uso paulino subraya la gracia recibida: aunque era el menos digno, recibió el privilegio de proclamar el evangelio a los gentiles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1648', 'spa', 'Eleazar, ancestro de Jesús en la genealogía de Mateo', 'La forma griega del nombre hebreo que significa ''Dios ha ayudado'', refiriéndose a un ancestro de Jesús. Eleazar aparece dos veces en Mateo 1:15, listado en la porción post-exílica de la genealogía. Se conoce poco de este individuo más allá de su lugar en el linaje. El nombre era común en el judaísmo post-exílico, llevado por varios sacerdotes y líderes incluyendo el hijo de Aarón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1649', 'spa', 'reprensión, reproche, convicción; el acto de reprender o exponer una falta', 'Este sustantivo significa reprensión, reproche o convicción: el acto de exponer y corregir una falta. En 2 Pedro 2:16, Balaam recibió "reprensión por su transgresión" cuando su asna habló. El término puede significar refutación en una argumentación o corrección moral. Aquí se refiere a la extraordinaria reprensión que detuvo la locura de Balaam. El sustantivo abarca tanto el acto de reprender como la convicción o exposición del pecado que resulta de ello.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1650', 'spa', 'prueba, evidencia, convicción, demostración, reprensión', 'Este sustantivo significa prueba, evidencia o refutación. 2 Timoteo 3:16 lo enumera entre los usos de la Escritura—enseñanza, reprensión, corrección, instrucción—mientras que Hebreos 11:1 define la fe como ''la convicción de lo que no se ve''. El sentido clásico de la palabra incluía el interrogatorio cruzado y la prueba para refutación. El uso neotestamentario enfatiza tanto la reprensión correctiva como la evidencia demostrativa, la comprobación de la realidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1651', 'spa', 'Reprender, convencer de maldad o exponer lo oculto — correccion verbal que saca la verdad a la luz. Palabra de fuerza moral y judicial, ἐλέγχω transmi', 'Reprender, convencer de maldad o exponer lo oculto — correccion verbal que saca la verdad a la luz. Palabra de fuerza moral y judicial, ἐλέγχω transmite el sentido de confrontacion que busca la restauracion. En los Evangelios, Jesus instruye a los creyentes a reprender en privado al hermano que peca (Mt 18:15), mientras que el Evangelio de Juan revela la obra del Espiritu de convencer al mundo de pecado (Jn 16:8). Tambien puede significar exponer obras ocultas, como en Ef 5:11-13, donde la luz misma se convierte en agente de revelacion. A traves de los tres sentidos corre un hilo comun: la verdad confrontando la falsedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1652', 'spa', 'digno de lástima, miserable, lamentable, desdichado', 'Este adjetivo significa digno de lástima o miserable, describiendo a alguien que merece compasión. Pablo lo usa en 1 Corintios 15:19 declarando que los cristianos serían los más dignos de lástima si Cristo no hubiera resucitado, y Apocalipsis 3:17 lo aplica a la miseria autoengañada de la iglesia de Laodicea. La palabra enfatiza el estado patético de quienes merecen compasión. El uso clásico incluía tanto ''lastimoso'' (que evoca lástima en otros) como ''lamentable'' (estar en un estado miserable).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1653', 'spa', 'Tener misericordia, mostrar compasión; en pasiva, recibir o ser objeto de misericordia.', 'Tener misericordia, mostrar compasión; en pasiva, recibir o ser objeto de misericordia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1654', 'spa', 'limosna, caridad, obra de misericordia — dinero o ayuda entregada por compasión hacia los pobres. Ἐλεημοσύνη deriva de ἔλεος (''misericordia, piedad'') ', 'limosna, caridad, obra de misericordia — dinero o ayuda entregada por compasión hacia los pobres. Ἐλεημοσύνη deriva de ἔλεος (''misericordia, piedad'') y originalmente significaba un acto de compasión. Para el período helenístico, y especialmente en el uso judío y cristiano, se había estrechado para designar la dádiva caritativa a los pobres — la limosna como expresión concreta de la misericordia. La enseñanza de Jesús en Mateo 6:2-4 define el perfil neotestamentario de esta palabra: dar limosna sin ostentación, sin que la mano izquierda sepa lo que hace la derecha. Lucas enfatiza su potencia espiritual: ''dad limosna, y todo os será limpio'' (Lc 11:41), ''vended vuestros bienes y dad limosna'' (Lc 12:33). En Hechos, las oraciones y limosnas de Cornelio suben como memorial delante de Dios (Hch 10:2, 4, 31).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1655', 'spa', 'misericordioso, compasivo, que muestra misericordia', 'Este adjetivo describe a alguien que es misericordioso o compasivo. Jesús lo usa en Mateo 5:7 en las Bienaventuranzas—''Bienaventurados los misericordiosos''—y Hebreos 2:17 lo aplica a Cristo al convertirse en un sumo sacerdote misericordioso. La palabra enfatiza la compasión activa y la disposición para mostrar misericordia. En el uso clásico y septuagintal se describía frecuentemente el carácter misericordioso de Dios, haciendo de la misericordia un atributo divino que los humanos están llamados a reflejar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1656', 'spa', 'Misericordia, compasión, fidelidad al pacto — la piedad activa de Dios que rescata al indefenso y cumple sus promesas.', 'Misericordia, compasión, fidelidad al pacto — la piedad activa de Dios que rescata al indefenso y cumple sus promesas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1657', 'spa', 'Libertad, emancipación — el estado de ser libre, especialmente de la esclavitud del pecado, la ley o la corrupción. El sustantivo ἐλευθερία (eleutheri', 'Libertad, emancipación — el estado de ser libre, especialmente de la esclavitud del pecado, la ley o la corrupción. El sustantivo ἐλευθερία (eleutheria) designa la libertad, empleado principalmente para la liberación teológica del pecado, la ley mosaica y la corrupción cósmica. La creación aguarda ''la libertad de la gloria de los hijos de Dios'' (Ro 8:21). ''Donde está el Espíritu del Señor, allí hay libertad'' (2 Co 3:17). La carta de Pablo a los Gálatas gira en torno a este concepto: espías se infiltraron para socavar ''nuestra libertad en Cristo'' (Gá 2:4), y ''para libertad Cristo nos hizo libres'' (Gá 5:1). Sin embargo, la libertad no debe convertirse en ''ocasión para la carne'' (Gá 5:13; 1 P 2:16). Santiago llama a la Torá ''la ley de la libertad'' (Stg 1:25; 2:12).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1658', 'spa', 'Libre — no esclavizado, liberado; que posee la condición legal o espiritual de persona libre.', 'Libre — no esclavizado, liberado; que posee la condición legal o espiritual de persona libre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1659', 'spa', 'Liberar, poner en libertad; soltar de la esclavitud, el pecado o el poder de la muerte y la ley.', 'Un verbo poderoso de liberación que significa poner en libertad de la esclavitud o la servidumbre. En la enseñanza de Jesús, conocer la verdad hace libres a las personas (Juan 8:32), y ''si el Hijo os libertare, seréis verdaderamente libres'' (Juan 8:36). Pablo desarrolla esto en toda una teología de la libertad: los creyentes han sido liberados del pecado para hacerse siervos de la justicia (Romanos 6:18, 22), librados de la ley del pecado y de la muerte por el Espíritu de vida (Romanos 8:2), y la creación misma gime con la esperanza de ser liberada de su esclavitud a la corrupción (Romanos 8:21). La evidencia multilingüe apunta consistentemente a la liberación de una opresión, no a un mero permiso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1660', 'spa', 'venida, llegada, advenimiento; el acto de venir o presentarse', 'Este sustantivo significa venida o llegada, usado frecuentemente para apariciones significativas. En Hechos 7:52, Esteban acusa a los antepasados de sus oyentes de haber perseguido a los profetas que anunciaron de antemano "la venida del Justo". El término puede referirse a llegadas ordinarias, pero aquí lleva un peso escatológico: el advenimiento del Mesías. En el uso clásico incluye llegadas a la vida o entradas significativas. El sustantivo subraya la anticipación profética del primer advenimiento de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1661', 'spa', 'de marfil, hecho de marfil; describe objetos fabricados con colmillos de elefante', 'Este adjetivo significa hecho de marfil, y describe objetos elaborados a partir de colmillos de elefante. En Apocalipsis 18:12, aparece en la lista de artículos de lujo comercializados en «Babilonia», mercancías costosas cuya pérdida lamentan los mercaderes. El marfil era un material sumamente apreciado en el mundo antiguo, empleado en incrustaciones decorativas, muebles y ornamentos. El término evoca riqueza y ostentación, como parte del retrato de la opulencia de Babilonia y del juicio que destruye su comercio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1662', 'spa', 'Eliakím, nombre propio que significa «Dios levanta»; antepasado de Jesús en las genealogías de Mateo y Lucas', 'El nombre hebreo Eliakím (אֶלְיָקִים) significa «Dios levanta» o «Dios establece», compuesto de El (Dios) y qum (levantar/establecer). En el Nuevo Testamento aparece exclusivamente en las genealogías de Jesús, representando ancestros postexílicos en la línea davídica. El nombre en sí es teológicamente sugerente — «Dios levanta» — apuntando a la soberanía divina que preservó el linaje mesiánico a través de generaciones oscuras entre el exilio y el nacimiento de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1663', 'spa', 'Eliézer; nombre hebreo que significa ''Dios es mi ayuda'', antepasado de Jesús en la genealogía de Lucas', 'Es la transliteración griega del nombre hebreo Eliézer, que significa «Dios es mi ayuda». En Lucas 3:29, Eliézer aparece en la genealogía de Jesús como uno de los antepasados entre David y Cristo. El nombre en sí constituye una confesión de fe, reflejo de la práctica israelita de plasmar verdades teológicas en los nombres personales. Varios personajes del Antiguo Testamento llevaron este nombre, el más célebre siendo el siervo de Abraham, pero Lucas se refiere a un ancestro de Cristo por lo demás desconocido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1664', 'spa', 'Eliud, antepasado de Jesús en la genealogía de Mateo', 'Este nombre propio aparece en Mateo 1:14-15, refiriéndose a un antepasado de Jesús en el período post-exílico. Eliud está en la línea genealógica entre Aquim y Eleazar. Se conoce poco de este individuo más allá de su ubicación en el linaje de Jesús. El nombre no aparece en las genealogías del Antiguo Testamento, sugiriendo que Mateo pudo haber tenido acceso a registros genealógicos adicionales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1665', 'spa', 'Elisabet; esposa del sacerdote Zacarías y madre de Juan el Bautista.', 'Forma griega del nombre hebreo Elisheba (''mi Dios es juramento'' o ''Dios es abundancia''), que en el Nuevo Testamento identifica a la esposa del sacerdote Zacarías y madre de Juan el Bautista. Aparece exclusivamente en la narración de la infancia de Lucas (Lucas 1:5-80), donde se la describe como justa, estéril en su vejez y milagrosamente encinta, un eco deliberado de Sara, Ana y otras madres estériles en la historia de Israel. Su gozoso reconocimiento al sentir saltar al niño de María en su vientre (Lucas 1:41-44) constituye un momento clave en la teología lucana del cumplimiento profético.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1666', 'spa', 'Eliseo; nombre hebreo que significa ''Dios es salvación'', el profeta que sucedió a Elías', 'Es la forma griega de Eliseo, el profeta que sucedió a Elías en el siglo IX a.C. En Lucas 4:27, Jesús menciona a Eliseo para ilustrar que la misericordia de Dios se extiende más allá de las fronteras de Israel: había muchos leprosos en Israel, pero solo Naamán el sirio fue sanado. La referencia enfurece a su audiencia en Nazaret, que se indigna ante la implicación. El ministerio de Eliseo, marcado por milagros de compasión, prefigura la propia misión inclusiva de Jesús tanto hacia gentiles como hacia judíos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1667', 'spa', 'enrollar, arrollar, envolver', 'Este verbo significa enrollar o envolver, como un rollo. Hebreos 1:12 cita el Salmo 102 sobre enrollar los cielos como un vestido, y Apocalipsis 6:14 describe el cielo enrollándose como un pergamino en el juicio. La palabra enfatiza la acción de arrollar o plegar algo flexible. El uso clásico incluía enrollar, torcer y arrollar varios objetos, particularmente pergaminos y vestiduras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1668', 'spa', 'Llaga, úlcera, herida supurante; lesión cutánea abierta y dolorosa, a menudo símbolo de juicio divino', 'El sustantivo ἕλκος designa una herida, especialmente una llaga supurante o úlcera: una lesión abierta, dolorosa y frecuentemente infectada. En el uso bíblico aparece en contextos de aflicción extrema: el mendigo Lázaro cubierto de llagas (Lucas 16) y las llagas semejantes a plagas de los juicios de Apocalipsis. La medicina antigua ofrecía poco alivio para la ulceración crónica, por lo que tales padecimientos eran emblema tanto de la miseria física como, a veces, del desagrado divino. La llaga visible en la piel hace tangible la corrupción espiritual o moral invisible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1669', 'spa', 'ulcerarse, estar cubierto de llagas; padecer heridas abiertas o lesiones supurantes', 'Este verbo significa estar cubierto de llagas o úlceras, sufrir de heridas abiertas. En Lucas 16:20 describe a Lázaro en la parábola, un mendigo «cubierto de llagas» que yacía a la puerta del rico. El participio perfecto pasivo sugiere una condición asentada y lastimosa: está completamente ulcerado, con el cuerpo devastado por heridas sin tratar. Este detalle intensifica el contraste entre el sufrimiento de Lázaro y la comodidad del rico, preparando la inversión de sus destinos en la vida venidera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1670', 'spa', 'Arrastrar, tirar, jalar; acarreo físico por la fuerza, o atracción espiritual divina.', 'El verbo ἕλκω abarca todo el espectro desde la fuerza bruta física hasta la misteriosa iniciativa divina. En su sentido concreto, se arrastran redes repletas de peces hasta la orilla (Juan 21:6, 11), Pedro desenvaina una espada (Juan 18:10), y Pablo y Silas son arrastrados ante los magistrados (Hechos 16:19). Pero en dos pasajes de enorme peso teológico, Jesús declara ''Nadie puede venir a mí si el Padre no lo atrae'' (Juan 6:44) y ''Yo, cuando sea levantado, atraeré a todos hacia mí'' (Juan 12:32). La evidencia multilingüe confirma la distinción: el español usa ''arrastrar'' para la fuerza física y ''atraer'' para el sentido espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1671', 'spa', 'Grecia, Hélade; las regiones de habla griega del Mediterráneo, en particular la Grecia continental', 'Este sustantivo designa a Grecia o la Hélade, originalmente el nombre de una región en Tesalia que terminó aplicándose a toda la Grecia continental y, en sentido amplio, a las tierras de habla griega. En Hechos 20:2, Pablo recorre Macedonia y llega a «Grecia» (probablemente Acaya, la provincia romana). El término evoca el mundo clásico, la esfera cultural y lingüística que Pablo navegó en sus viajes misioneros. Su estancia en Grecia incluyó un ministerio significativo en Corinto y Atenas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1672', 'spa', 'Griego, heleno — persona de cultura griega o, más ampliamente en el NT, cualquier gentil no judío.', 'Griego, heleno — persona de cultura griega o, más ampliamente en el NT, cualquier gentil no judío.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1673', 'spa', 'griego, helénico, en lengua o manera griega', 'Este adjetivo significa griego o helénico, refiriéndose al idioma, cultura o etnicidad. Lucas 23:38 menciona la inscripción en la cruz escrita en griego (entre otros idiomas), y Apocalipsis 9:11 da el nombre griego Apolión. La palabra podía denotar el idioma griego, las costumbres griegas o el pueblo griego colectivamente. Distinguía la cultura helénica de contextos bárbaros o judíos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1674', 'spa', 'mujer griega, mujer gentil de cultura helénica', 'Este sustantivo femenino denota una mujer griega o mujer gentil influenciada por la cultura helénica. Marcos 7:26 identifica a la mujer sirofenicia como griega (étnicamente gentil), y Hechos 17:12 menciona mujeres griegas de alta posición que creyeron en Berea. El término podía indicar herencia étnica griega o cultura gentil helenizada. Distinguía a mujeres de trasfondo judío o contextos bárbaros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1675', 'spa', 'Helenistas, judíos de habla griega; judíos de la diáspora cuya lengua principal era el griego en lugar del hebreo o arameo', 'El término Ἑλληνιστής (de Ἑλληνίζω, «hablar griego») designa a los judíos de habla griega, especialmente aquellos de la diáspora cuya lengua materna era el griego y no el hebreo ni el arameo. En la iglesia primitiva de Jerusalén, esto generó una división cultural y lingüística respecto a los «hebreos» (judíos palestinos que hablaban arameo). Los helenistas mantenían la fe y la práctica judía, pero la expresaban a través del idioma griego y, con frecuencia, de formas culturales helenísticas, lo cual producía tanto riqueza como tensión en la comunidad mixta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1676', 'spa', 'en griego, en lengua griega', 'Este adverbio significa ''en griego'' o ''en lengua griega''. Juan 19:20 indica que la inscripción en la cruz de Jesús estaba escrita en hebreo, griego y latín, mientras que Hechos 21:37 registra a Pablo preguntando si el tribuno habla griego. La expresión denota específicamente el idioma griego como medio de comunicación. También podría significar ''al estilo griego'', pero el uso en el Nuevo Testamento es lingüístico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1677', 'spa', 'cargar a cuenta, imputar, contabilizar', 'Este verbo significa cargar algo a la cuenta de alguien, contabilizar o imputar. Romanos 5:13 declara que el pecado no se imputa donde no hay ley, y Filemón 18 presenta a Pablo pidiendo que cualquier falta se cargue a su cuenta. La palabra combina ''en'' y ''contabilizar'', sugiriendo un asiento en un libro de cuentas. Se usa tanto para contabilidad financiera como para imputación metafórica de responsabilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1678', 'spa', 'Elmadám; antepasado de Jesús en la genealogía de Lucas, por lo demás desconocido', 'Este nombre aparece en Lucas 3:28 como uno de los antepasados de Jesús en la genealogía que traza su linaje hasta Adán. Elmadám es una figura completamente desconocida fuera de este pasaje, uno de los muchos nombres que Lucas incluye y que no aparecen en el Antiguo Testamento. La inclusión de personajes tan oscuros subraya la exhaustividad del registro genealógico de Lucas y el arraigo histórico de la humanidad de Jesús. Cada generación, conocida o desconocida, forma parte de la obra paciente de Dios para traer al Mesías al mundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1679', 'spa', 'Esperar, aguardar; poner confianza firme en; (pasivo) aquello que se espera.', 'Esperar, aguardar; poner confianza firme en; (pasivo) aquello que se espera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1680', 'spa', 'Esperanza, expectativa — anticipación confiada de un bien futuro fundada en la confianza o la promesa divina', 'Ἐλπίς designa la postura de expectativa confiada hacia el futuro, una de las grandes virtudes teológicas del Nuevo Testamento junto con la fe y el amor (1 Co 13:13). En sus 53 apariciones, abarca desde la esperanza viva fundada en la resurrección de Cristo (1 Pe 1:3) hasta la esperanza paulina de la resurrección de los muertos (Hch 23:6; 24:15) y la ''esperanza guardada en los cielos'' (Col 1:5). En Hechos 16:19, de modo singular, el vocablo toma un giro secular e irónico: la ''esperanza de ganancia'' de los amos se desvanece cuando Pablo expulsa al espíritu adivinador. El concepto converge en todas las lenguas en un sentido cálido y profundo: esperanza que implica confianza, no mero deseo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1681', 'spa', 'Elimas; nombre griego o árabe de Bar-Jesús, el mago que se opuso a Pablo en Chipre', 'Este nombre designa al mago que se opuso a Pablo y Bernabé en Chipre en Hechos 13:8. Llamado también Bar-Jesús, Elimas era un falso profeta judío en la corte del procónsul Sergio Paulo. Cuando intentó apartar al procónsul de la fe, Pablo lo dejó ciego. El nombre «Elimas» posiblemente derive de una palabra árabe o aramea que significa «mago» o «sabio», paralela al término «mago» (magus). Su oposición y castigo constituyen una confrontación dramática entre el evangelio y el poder oculto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1682', 'spa', 'Eloí, arameo para ''Dios mío''', 'Esta es una transliteración griega del arameo אֱלָהִי (''elahi), que significa ''Dios mío''. Aparece en Marcos 15:34 dos veces en el grito de Jesús desde la cruz: ''¿Eloí, Eloí, lema sabactani?''—Dios mío, Dios mío, ¿por qué me has desamparado? La preservación del arameo original enfatiza la auténtica expresión de la angustiosa cita de Jesús del Salmo 22:1.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1683', 'spa', 'Mí mismo -- pronombre reflexivo de primera persona que indica al hablante como sujeto y objeto de la acción.', 'Mí mismo -- pronombre reflexivo de primera persona que indica al hablante como sujeto y objeto de la acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1684', 'spa', 'Entrar, embarcarse; subir a un barco o embarcacion. ἐμβαίνω significa entrar o abordar algo, y en el Nuevo Testamento se usa exclusivamente para subir', 'Entrar, embarcarse; subir a un barco o embarcacion. ἐμβαίνω significa entrar o abordar algo, y en el Nuevo Testamento se usa exclusivamente para subirse a un barco. Jesus y sus discipulos cruzan constantemente el Mar de Galilea, y este verbo marca esas transiciones: embarcarse despues del Sermon del Monte (Mt 8:23), antes de la alimentacion de los cinco mil (Mt 14:22) y en muchos otros cruces. La forma compuesta (ἐν- + βαίνω, ''pisar dentro'') hace vivida la accion fisica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1685', 'spa', 'arrojar dentro, lanzar a; depositar o echar algo en un lugar con fuerza o finalidad', 'Este verbo significa arrojar dentro, lanzar a o depositar algo en un lugar. En Lucas 12:5, Jesús advierte que se debe temer a aquel que, después de dar muerte, tiene autoridad «para echar en el infierno». El verbo enfatiza el acto de arrojar o consignar a alguien a un lugar, en este caso la Gehena. En el uso clásico incluye lanzar cosas a animales o poner algo en manos de alguien. El término subraya la autoridad divina y la finalidad del juicio: Dios puede echar al infierno, un destino más temible que la muerte física.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1686', 'spa', 'mojar en, sumergir en líquido', 'Este verbo significa mojar algo en un líquido. Ambas apariciones están en contextos de la Última Cena: Mateo 26:23 y Marcos 14:20 describen a alguien mojando en el plato con Jesús, identificando al traidor. La palabra enfatiza la acción de mojar pan o comida en un plato común o salsa. El prefijo ''en-'' intensifica el verbo básico de mojar, enfatizando el aspecto de ''dentro de''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1687', 'spa', 'entrar en, entrometerse, tomar posesión de; inmiscuirse o adentrarse en algo indebidamente', 'Este verbo puede significar entrar en, entrometerse o tomar posesión de algo. En Colosenses 2:18, Pablo advierte contra quienes descalifican a los creyentes «insistiendo en prácticas ascéticas y culto a los ángeles, adentrándose en visiones». La expresión «entrando en» visiones sugiere inmiscuirse en experiencias visionarias o reclamar acceso indebido a conocimientos místicos. En el uso clásico incluye entrar en cuevas sagradas o tomar posesión de una herencia. El punto de Pablo es que tales prácticas son presuntuosas y desvían de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1688', 'spa', 'hacer embarcar, poner a bordo; hacer que alguien suba a un navío', 'Este verbo significa poner a alguien a bordo de un barco, hacer embarcar. En Hechos 27:6, un centurión encuentra un navío alejandrino que navegaba hacia Italia y «nos hizo embarcar». El verbo enfatiza la acción del centurión al gestionar el pasaje y hacer subir a Pablo y sus compañeros a la embarcación. En el uso clásico incluye embarcar tropas en navíos o recolocar articulaciones dislocadas. Aquí el sentido es directo: facilitar el embarque para el viaje a Roma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1689', 'spa', 'Mirar fijamente, contemplar con atención — fijar los ojos en alguien con una mirada intensa y deliberada. El verbo ἐμβλέπω (emblepo) significa mirar d', 'Mirar fijamente, contemplar con atención — fijar los ojos en alguien con una mirada intensa y deliberada. El verbo ἐμβλέπω (emblepo) significa mirar directa e intensamente a alguien, implicando atención concentrada en lugar de un vistazo casual. Compuesto de ἐν (''en'') y βλέπω (''ver''), transmite la idea de mirar ''dentro'' de una persona. Jesús ordena a los discípulos ''mirar'' las aves como lección sobre la providencia (Mt 6:26). Él ''miró'' al joven rico y lo amó (Mr 10:21). El ciego sanado ''miró fijamente y fue restaurado'' (Mr 8:25). Tras la negación de Pedro, el Señor se volvió y ''lo miró'' (Lc 22:61). Juan el Bautista ''miró a Jesús caminando'' y lo declaró Cordero de Dios (Jn 1:36).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1690', 'spa', 'Conmoverse profundamente, gemir interiormente o advertir severamente; expresa emoción intensa: indignación, dolor o urgencia.', 'Verbo de notable intensidad que originalmente describía el resoplido de los caballos, aplicado en el NT a las poderosas respuestas emocionales de Jesús. Ante la tumba de Lázaro, Jesús «se conmovió profundamente en espíritu» y «gimió dentro de sí» (Jn 11:33, 38), expresión de dolor y quizá ira contra la muerte misma. Anteriormente, Jesús «advierte severamente» a los ciegos sanados y a un leproso que guarden silencio sobre sus milagros (Mt 9:30; Mc 1:43). En Marcos 14:5, los presentes «reprenden» a la mujer que derramó perfume sobre Jesús. El término transmite una conmoción visceral que va más allá de la simple emoción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1691', 'spa', 'Yo (pronombre de primera persona); forma enfática: yo mismo, yo por mi parte', 'Pronombre de primera persona que aparece en diversas formas dialectales a lo largo de la literatura griega. El nominativo ἐγώ (a veces ἐγών) significa simplemente «yo», aunque el griego suele omitirlo cuando la desinencia verbal ya indica la persona. Cuando se expresa, normalmente lleva énfasis: «yo mismo» o «yo, a diferencia de otros». La forma reforzada ἐγώγε, frecuente en el ático, significa «yo al menos» o «yo por mi parte». Los casos oblicuos provienen de una raíz distinta: genitivo ἐμοῦ («de mí»), dativo ἐμοί («a mí»), acusativo ἐμέ («me»). Las formas enclíticas (μου, μοι, με) ofrecen variantes átonas. Este pronombre permite afirmaciones personales y contrastes en todo el discurso griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1692', 'spa', 'vomitar, arrojar de la boca; expulsar con repugnancia o rechazo visceral', 'Este verbo significa vomitar o arrojar de la boca, ya sea por enfermedad o por asco profundo. En Apocalipsis 3:16, Cristo resucitado advierte a la iglesia de Laodicea: «Por cuanto eres tibio, y no frío ni caliente, te vomitaré de mi boca.» El verbo transmite un rechazo visceral: la tibieza espiritual provoca una respuesta de náusea que conduce a la expulsión. La imagen es deliberadamente impactante: la mediocridad espiritual resulta tan repulsiva para Cristo que Él vomitará a quienes permanezcan en ella. La amenaza busca provocar un arrepentimiento urgente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1693', 'spa', 'enfurecerse, enloquecer de ira; estar poseído por una rabia extrema contra alguien', 'Este verbo significa enfurecerse o enloquecer de ira, generalmente dirigida contra alguien. En Hechos 26:11, Pablo recuerda su celo previo a la conversión: «Enfurecido sobremanera contra ellos, los perseguí incluso hasta ciudades extranjeras.» El participio presente sugiere una furia constante: estaba permanentemente enfurecido, impulsado por un fanatismo irracional a perseguir a los cristianos más allá de Judea. El verbo capta la intensidad de su oposición, una locura que luego se convierte en testimonio del poder transformador del encuentro con Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1694', 'spa', 'Emanuel; nombre hebreo que significa ''Dios con nosotros,'' título mesiánico aplicado a Jesús', 'Esta es la transliteración griega del nombre hebreo Emanuel, que significa «Dios con nosotros». En Mateo 1:23, el ángel interpreta el nacimiento virginal citando Isaías 7:14: el niño será llamado Emanuel. El nombre encapsula el misterio de la encarnación: Dios habitando entre su pueblo en carne humana. Aunque Jesús no fue llamado literalmente Emanuel, el título expresa su identidad y misión: en Él, Dios está verdaderamente presente con nosotros, cumpliendo la profecía de Isaías de un modo que supera con creces su contexto original.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1695', 'spa', 'Emaús; aldea cercana a Jerusalén donde Jesús se apareció a dos discípulos tras su resurrección', 'Este topónimo se refiere a una aldea situada a unos once kilómetros (sesenta estadios) de Jerusalén. En Lucas 24:13, dos discípulos caminan hacia Emaús el día de la resurrección de Jesús cuando el Señor resucitado se les une, aunque no lo reconocen. Él les expone las Escrituras que hablan de sí mismo, y sus corazones arden dentro de ellos. Solo cuando parte el pan lo reconocen, y entonces Él desaparece. Emaús se convierte en escenario de una de las apariciones postresurrección más queridas, un relato de ojos abiertos y fe reavivada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1696', 'spa', 'Permanecer en, perseverar en; mantenerse firme en un compromiso o lugar', 'Compuesto de ἐν + μένω, este verbo intensifica la idea de permanecer enfatizando la interioridad: quedarse dentro de un compromiso, un lugar o un pacto. Pablo y Bernabé exhortan a los nuevos creyentes a perseverar en la fe (Hch 14:22), mientras que el propio Pablo permaneció dos años completos en Roma (Hch 28:30). El sentido pactual es más agudo en Hebreos 8:9 y Gálatas 3:10, donde la falta de permanencia en el pacto o la ley de Dios acarrea consecuencias. El español ''permanecer'' capta bien la persistencia durativa que el verbo exige.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1697', 'spa', 'Hamor; nombre hebreo que significa ''asno,'' príncipe cananeo de quien Abraham compró tierra en Siquem', 'Esta es la forma griega de Hamor, el príncipe heveo de Siquem que vendió tierra a Abraham (Génesis 33:19). En Hechos 7:16, Esteban menciona esta compra de tierra en su discurso, aunque condensa detalles de la adquisición de Abraham en Siquem con la sepultura en Hebrón. Hamor fue padre de Siquem, quien deshonró a Dina, lo que desencadenó la violenta venganza de los hijos de Jacob. El nombre aparece en el relato de la historia patriarcal de Israel, señalando la adquisición de tierras que llegarían a ser significativas en el asentamiento de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1698', 'spa', 'De mí, mi (genitivo); a mí (dativo); me (acusativo) — casos oblicuos del pronombre de primera persona', 'Formas de caso oblicuo del pronombre de primera persona, que permiten referirse a «mí» en diversas relaciones gramaticales. El genitivo ἐμοῦ (enclítico μου) significa «de mí» o funciona como posesivo «mi». El dativo ἐμοί (enclítico μοι) significa «a mí» o «para mí», indicando objeto indirecto o beneficiario. El acusativo ἐμέ (enclítico με) funciona como objeto directo «me». Estas formas, derivadas de una raíz diferente al nominativo ἐγώ, aparecen en diversas grafías dialectales a lo largo de la literatura griega. Las variantes enclíticas se emplean cuando no se requiere énfasis. En conjunto, permiten al hablante situarse en distintos roles gramaticales dentro del discurso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1699', 'spa', 'Mi, mío — pronombre posesivo de primera persona, usado como atributo (''mi Padre'') o sustantivado (''lo mío'')', 'Ἐμός es la forma posesiva enfática de la primera persona en griego, más fuerte que el simple genitivo μου. Cuando Jesús dice ''mi comida es hacer la voluntad del que me envió'' (Jn 4:34) o ''mi paz os doy'' (Jn 14:27), la forma enfática subraya posesión personal y relación íntima. Usado de modo sustantivo, significa ''lo mío'': como en ''todo lo mío es tuyo y lo tuyo es mío'' (Jn 17:10). El español distingue entre el atributivo mi y el sustantivo mío, reflejando la misma distinción funcional del griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1700', 'spa', 'Yo (pronombre de primera persona singular); el hablante o escritor que se identifica a sí mismo', 'El pronombre de primera persona marca la presencia y la agencia del hablante en el discurso. En griego antiguo aparece en formas reforzadas como ἔγωγε («yo al menos», «por mi parte») que añaden énfasis o contraste. Los casos oblicuos derivan de una raíz diferente, dando lugar al conocido genitivo ἐμοῦ y al dativo ἐμοί. Los autores bíblicos emplean este pronombre para expresar testimonio personal, autorrevelación divina y afirmaciones enfáticas sobre identidad y autoridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1701', 'spa', 'burla, escarnio, mofa, ridiculización', 'Este sustantivo significa burla o escarnio. Hebreos 11:36 enumera las burlas entre los sufrimientos soportados por los testigos fieles, y 2 Pedro 3:3 advierte de burladores que vendrán con escarnio en los últimos días. La palabra enfatiza el ridículo despectivo dirigido a los creyentes. Captura el desprecio y el menosprecio expresado mediante palabras y comportamiento burlón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1702', 'spa', 'Burlarse, ridiculizar o tratar con desprecio; engañar o hacer quedar en ridículo a alguien mediante un ardid. Un verbo de crueldad y escarnio que reco', 'Burlarse, ridiculizar o tratar con desprecio; engañar o hacer quedar en ridículo a alguien mediante un ardid. Un verbo de crueldad y escarnio que recorre como un hilo oscuro los relatos de la Pasión. Los soldados se burlan de Jesús (Mt 27:29, 31), los transeúntes lo ridiculizan en la cruz (Mt 27:41) y los sumos sacerdotes se suman al ultraje (Mc 15:20). La palabra combina desprecio físico y verbal: escupir, vestir con púrpura real, inclinarse en falso homenaje. Sin embargo, su primera aparición evangélica revela un matiz más agudo: cuando los magos no regresan, Herodes se da cuenta de que ha sido ''burlado'', es decir, superado en astucia y puesto en ridículo (Mt 2:16), donde el engaño, más que la burla directa, es el sentido central.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1703', 'spa', 'quien se burla o ridiculiza, especialmente en asuntos de fe; escarnecedor que desprecia verdades sagradas', 'Este término aparece en advertencias sobre escépticos que ridiculizan las promesas del regreso de Dios. Tanto Pedro como Judas lo usan para describir a quienes andan según sus propias pasiones mientras se burlan de la esperanza de la venida de Cristo. La traducción consistente como ''burladores'' o ''escarnecedores'' en diversos idiomas (español burladores, francés moqueurs, alemán Spötter) enfatiza la naturaleza despreciativa de su discurso. Estos no son simples dudadores ocasionales sino ridiculizadores deliberados de la verdad divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1704', 'spa', 'caminar entre, habitar entre; moverse activamente dentro de una comunidad en estrecha comunión', 'Este verbo compuesto significa caminar entre o habitar en medio de personas. En 2 Corintios 6:16, Pablo cita la promesa del Antiguo Testamento: "Habitaré entre ellos y andaré entre ellos, y seré su Dios." El verbo enfatiza la presencia activa y personal de Dios en medio de su pueblo, no distante sino moviéndose entre ellos en comunión íntima. El uso clásico incluye ir y venir en una reunión. Pablo aplica esto a la iglesia como templo de Dios: el Espíritu habita y camina entre los creyentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1705', 'spa', 'Llenar, saciar o proveer abundantemente; satisfacer con alimento o provisión hasta la plenitud.', 'Describe el acto de llenar hasta la capacidad o satisfacer plenamente, frecuentemente con alimento pero también con provisión espiritual y material. En el Magnificat de María, Dios «llenó de bienes a los hambrientos» mientras despidió vacíos a los ricos (Lc 1:53). Jesús advierte que quienes ahora están saciados tendrán hambre (Lc 6:25), y tras el milagro de la multiplicación los pedazos llenan doce canastas porque todos «fueron saciados» (Jn 6:12). Pablo habla de Dios llenando los corazones de sustento y alegría (Hch 14:17) y expresa su anhelo de «saciarse» de la compañía de los romanos (Ro 15:24).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1706', 'spa', 'Caer en un hoyo, trampa o situación perjudicial; caer entre peligros o circunstancias adversas.', 'Describe la acción de caer dentro de algo: un hoyo, una trampa o una situación peligrosa. Jesús lo emplea de forma concreta en sus parábolas: una oveja que cae en un hoyo en sábado (Mateo 12:11) y el ciego guiando a otro ciego hasta caer en un foso (Lucas 6:39). La parábola del buen samaritano habla de un hombre que ''cayó en manos de ladrones'' (Lucas 10:36). En las Epístolas Pastorales, Pablo traslada la imagen al peligro espiritual: un recién convertido envanecido puede caer en la condenación del diablo (1 Timoteo 3:6) o en su trampa (1 Timoteo 3:7). En todos los casos, el verbo implica la entrada involuntaria en una condición indeseable, ya sea física o espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1707', 'spa', 'enredarse o enmarañarse en algo; quedar atrapado en complicaciones que obstaculizan la libertad', 'La palabra evoca la imagen de quedar atrapado en una red o trampa, con aplicación metafórica a enredos espirituales y morales. Pablo advierte a Timoteo que un soldado no debe enredarse en asuntos civiles (2 Ti 2:4), mientras que Pedro describe la tragedia de quienes, habiendo escapado de las contaminaciones del pecado, se enredan nuevamente y son vencidos (2 Pe 2:20). El alemán ''verwickelt'' (complicado, enredado) y el español ''enredado'' capturan el sentido de quedar atrapado en algo que restringe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1708', 'spa', 'trenzado, entrelazado; el acto de tejer el cabello en estilos ornamentales', 'Este sustantivo se refiere al trenzado o entrelazado, especialmente del cabello. En 1 Pedro 3:3, Pedro instruye a las mujeres que su adorno no debe ser exterior: "el trenzado del cabello, el llevar joyas de oro o vestidos lujosos." No prohíbe estas cosas de manera absoluta, sino que advierte contra hacer de la apariencia externa el centro de la propia identidad. El uso clásico incluye el entretejido de raíces o el entrelazamiento matemático. Pedro contrasta el adorno exterior con la belleza interior de un espíritu apacible y sereno, que es precioso ante Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1709', 'spa', 'respirar, soplar; estar vivo, tener aliento y vida', 'Este verbo significa respirar, soplar o simplemente estar vivo. En Hechos 9:1, Saulo es descrito como "respirando amenazas y muerte contra los discípulos." El participio sugiere que exhalaba hostilidad; su mismo aliento estaba cargado de menaza contra los cristianos. El uso clásico incluye soplar sobre algo, tocar un instrumento de viento o simplemente vivir. Aquí la metáfora es vívida: la vida de Saulo estaba consumida por una oposición violenta contra la iglesia, cada respiro dedicado a la persecución, hasta que Cristo lo detuvo en el camino a Damasco.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1710', 'spa', 'dedicarse al comercio o negocio; explotar algo para ganancia, especialmente de manera inescrupulosa', 'Originalmente denotando viaje de negocios o comercio, el término desarrolla un matiz más negativo en el NT. Santiago lo usa respecto a comerciantes planeando empresas comerciales (Stg 4:13), mientras que Pedro lo emplea más peyorativamente sobre falsos maestros que explotan a creyentes con historias fabricadas (2 Pe 2:3). El rango desde ''comerciar'' neutral hasta ''mercadear'' explotador aparece en las traducciones, determinando el contexto si se trata de comercio honesto o explotación codiciosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1711', 'spa', 'comercio, negocio, actividad mercantil; la compraventa de bienes, especialmente por vía marítima', 'Este sustantivo significa comercio o negocio, refiriéndose frecuentemente a la actividad mercantil realizada por mar. En Mateo 22:5, aparece en la parábola de la fiesta de bodas: los invitados "se fueron, uno a su campo, otro a sus negocios." El término representa las preocupaciones mundanas que llevan a las personas a rechazar la invitación del rey. El uso clásico enfatiza el comercio marítimo, pero en sentido amplio abarca cualquier empresa comercial. La parábola advierte que incluso los negocios legítimos pueden convertirse en una distracción que nos impide responder al llamado de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1712', 'spa', 'centro de comercio, mercado, plaza comercial donde los mercaderes se reúnen para hacer negocios', 'Este término se refiere a un centro de comercio o mercado, un lugar donde se realizan transacciones comerciales. En el mundo antiguo, estos centros eran vitales para el intercambio económico y servían como puntos de encuentro para los mercaderes. Jesús usa esta palabra al purificar el templo en Juan 2:16, condenando a quienes habían convertido la casa de su Padre en un mercado. Esto subraya la mezcla inapropiada del espacio sagrado con la actividad comercial, profanando el propósito original del templo como lugar de adoración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1713', 'spa', 'Mercader o comerciante; persona que viaja para comprar y vender mercancías, especialmente por vía marítima.', 'Designa a un comerciante mayorista que importa mercancías, distinguiéndose en el griego clásico del minorista (κάπηλος). Jesús emplea la figura de manera positiva en la parábola del mercader que busca perlas finas y vende todo para adquirir la perla de gran precio (Mt 13:45). En cambio, Apocalipsis presenta un panorama muy distinto: los mercaderes de la tierra se enriquecen con el lujo de Babilonia (Ap 18:3, 11, 15) y lloran su caída porque nadie compra ya sus mercancías (Ap 18:23). El término evoca un traficante de gran escala, no un simple vendedor local.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1714', 'spa', 'incendiar, prender fuego, destruir con fuego; consumir o arrasar mediante llamas', 'Este verbo significa incendiar o prender fuego, generalmente con intención destructiva. Aparece en Mateo 22:7, en la parábola del banquete de bodas, donde el rey ''incendió su ciudad'' como respuesta a quienes rechazaron su invitación. El trasfondo léxico muestra que este término se usaba en textos clásicos como los de Homero para describir la quema de ciudades, enfatizando la destrucción total por fuego. Transmite el juicio divino mediante la consumación completa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1715', 'spa', 'Delante de, ante, en presencia de — marcador espacial y relacional de posición o rango', 'Ἔμπροσθεν funciona como preposición y como adverbio, indicando posición ''delante de'' o ''ante'' alguien o algo. Sus 48 apariciones neotestamentarias rigen abrumadoramente el genitivo, situando acciones o personas a la vista o en presencia de otro: las buenas obras brillando ''delante de los hombres'' (Mt 5:16), confesar a Cristo ''delante de mi Padre'' (Mt 10:32) o Judas yendo ''delante de'' la multitud (Lc 22:47). Jesús advierte contra practicar la justicia ''delante de los hombres para ser vistos'' (Mt 6:1), y el Bautista testifica que el que viene ''después de mí me ha precedido, porque era antes que yo'' (Jn 1:15, 30), donde ἔμπροσθεν transmite prioridad temporal y rango, no solo posición espacial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1716', 'spa', 'Escupir a alguien, expresando desprecio, burla o ultraje.', 'Un verbo visceral de degradación pública, usado exclusivamente en los Evangelios para describir la humillación de Jesús durante su Pasión. Los miembros del Sanedrín le escupen en el rostro tras el juicio (Mateo 26:67), los soldados romanos repiten la afrenta durante la burla (Mateo 27:30; Marcos 15:19), y el propio Jesús predice este trato de antemano (Marcos 10:34). Escupir a alguien constituía uno de los actos más degradantes en el mundo mediterráneo antiguo: una agresión contra el honor que traspasaba toda frontera cultural. El verbo conserva toda la crudeza física del acto, subrayando la profundidad del ultraje infligido al Mesías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1717', 'spa', 'visible, manifiesto, mostrado abiertamente; apareciendo a clara vista o hecho evidente a la percepción', 'La palabra lleva la idea de hacer visible lo que antes estaba oculto o en potencia. Dios hizo a Jesús manifiesto a testigos escogidos después de la resurrección (Hch 10:40), mientras que Pablo cita a Isaías acerca de Dios haciéndose manifiesto a quienes no lo buscaban (Ro 10:20). El trasfondo léxico incluye aparecer corporalmente entre los hombres y ser presentado abiertamente en tribunal. Las traducciones enfatizan consistentemente la cualidad de ser abiertamente visible o claramente evidente en lugar de oculto u oscuro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1718', 'spa', 'Dar a conocer o hacer visible; ya sea informar o denunciar formalmente ante las autoridades, o revelar, manifestar y hacer patente. Un verbo con dos á', 'Dar a conocer o hacer visible; ya sea informar o denunciar formalmente ante las autoridades, o revelar, manifestar y hacer patente. Un verbo con dos ámbitos de acción distintos en el Nuevo Testamento. En los pasillos legales de Hechos, describe el acto formal de presentar cargos o informar a un oficial romano: los sumos sacerdotes ''informan'' al comandante contra Pablo (Hch 23:15, 24:1, 25:2). Pero en los Evangelios y Hebreos, adquiere una cualidad luminosa: Jesús promete ''manifestarse'' a quienes lo aman (Jn 14:21-22), los santos resucitados ''aparecieron'' en Jerusalén (Mt 27:53), y Cristo ahora ''se presenta'' ante Dios en nuestro favor (Heb 9:24).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1719', 'spa', 'Atemorizado, aterrorizado; que se halla en estado de alarma o pavor ante un suceso sobrenatural o abrumador.', 'Adjetivo que describe el estado de estar sobrecogido por el miedo, casi siempre como respuesta a un encuentro divino o sobrenatural. Las mujeres en la tumba vacía quedan aterrorizadas ante los mensajeros angélicos (Lc 24:5), los discípulos se espantan cuando Jesús aparece entre ellos (Lc 24:37), Cornelio mira con temor al ángel que lo visita (Hch 10:4), y Félix se alarma cuando Pablo razona sobre el juicio venidero (Hch 24:25). En Ap 11:13, los sobrevivientes del terremoto quedan aterrorizados y dan gloria a Dios. El término implica un pavor profundo, no un simple susto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1720', 'spa', 'soplar sobre, insuflar; impartir aliento o espíritu soplando sobre alguien', 'Este verbo significa soplar sobre alguien o insuflar aliento, con frecuencia cargado de significado simbólico y espiritual. En Juan 20:22, Jesús resucitado sopla sobre sus discípulos y les dice ''Recibid el Espíritu Santo'', evocando el acto de Dios al insuflar vida en Adán en Génesis. El gesto comunica la impartición de la presencia y el poder divinos. Aunque en textos clásicos se usaba para soplar en flautas, el contexto bíblico apunta claramente a una acción vivificante y pneumatológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1721', 'spa', 'implantado, innato, congénito; plantado interiormente o inherente por naturaleza en alguien', 'Este adjetivo describe algo implantado o innato, ya sea naturalmente congénito o deliberadamente sembrado. En Santiago 1:21, se exhorta a los creyentes a recibir ''la palabra implantada'' que puede salvar sus almas. El término puede significar inherente por naturaleza (como la virtud innata en textos clásicos) o plantado a propósito (como árboles o ideas). Santiago lo emplea metafóricamente para la palabra de Dios sembrada en el corazón, contrastando la recepción externa con el arraigo interior profundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1722', 'spa', 'En, dentro de, entre; por medio de, con — la preposición locativo-instrumental que expresa posición, esfera, medio y asociación', 'La preposición más común del griego para indicar ubicación dentro de un espacio, tiempo o circunstancia, así como el medio o instrumento por el cual se realiza una acción, y la asociación o comunión con otros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1723', 'spa', 'tomar en los brazos, abrazar; gesto de afecto, bendición o protección', 'Este tierno verbo aparece solo en el Evangelio de Marcos, ambas veces describiendo a Jesús tomando niños en sus brazos. Después de enseñar sobre recibir el reino como un niño, Jesús tomó a un niño en sus brazos para ilustrar su punto (Mr 9:36). Más tarde, al bendecir a los niños traídos a él, los tomó en sus brazos y los bendijo (Mr 10:16). La acción transmite calidez, aceptación y cuidado paternal. La voz media enfatiza la acción personal y deliberada de Jesús al atraer a los niños cerca.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1724', 'spa', 'del mar, marino, acuático; relativo a criaturas o cosas que habitan en el mar', 'Este adjetivo describe criaturas o cosas pertenecientes al mar. En Santiago 3:7, aparece en una lista de categorías que los humanos han domesticado: animales terrestres, aves, criaturas marinas y reptiles. El término enfatiza el hábitat y la naturaleza marina de estos seres. En textos clásicos se aplicaba a dioses del mar como Poseidón, marineros, islas y vida marina. Santiago lo usa para resaltar el dominio que Dios otorgó al ser humano sobre toda la creación, contrastándolo con nuestra incapacidad para domar la lengua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1725', 'spa', 'en presencia de, delante de; usado para indicar posición ante la vista o conciencia de alguien', 'Esta preposición (que rige genitivo) denota presencia ante alguien, especialmente en contextos de adoración o conciencia divina. Zacarías sirve como sacerdote delante de Dios (Lucas 1:8), mientras Pedro declara que el corazón de Simón no es recto delante de Dios (Hechos 8:21). Aunque menos común que preposiciones similares, lleva un tono formal o solemne, enfatizando el estar en la presencia o vista de alguien. El uso septuagintal influyó en su aparición en el estilo griego más hebraico de Lucas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1726', 'spa', 'Delante de, en presencia de, a la vista de; preposición que indica posición frente a alguien, especialmente Dios o una asamblea.', 'Preposición que significa ''delante de'' o ''a la vista de'', con un matiz de visibilidad pública o conciencia divina. Zacarías e Isabel caminan de manera irreprochable ''delante de Dios'' (Lc 1:6), Jesús es un profeta poderoso en obra y palabra ''delante de Dios y de todo el pueblo'' (Lc 24:19), y José halla gracia ''delante de Faraón'' (Hch 7:10). El sentido de estar expuesto a la mirada de un observador le confiere mayor peso que un simple ''enfrente de'' espacial: implica rendición de cuentas y testimonio directo ante quien nos observa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1727', 'spa', 'Contrario, opuesto; posición espacial opuesta — resistencia en dirección, propósito o ubicación física.', 'El adjetivo ἐναντίος lleva el sentido griego clásico de ''puesto en contra'', ya sea un viento que sopla contra una barca, personas que actúan en oposición hostil, o alguien situado físicamente enfrente de otro. En los Evangelios, los discípulos de Jesús luchan contra un viento ''contrario'' (Mateo 14:24; Marcos 6:48), imagen vívida de fuerzas naturales que resisten el esfuerzo humano. En Hechos, el término se desplaza hacia la oposición interpersonal e ideológica: Pablo confiesa que antes creía necesario hacer muchas cosas ''contrarias'' al nombre de Jesús (Hechos 26:9). Una única ocurrencia en Marcos 15:39, donde el centurión se coloca ''enfrente'' de la cruz, conserva el sentido puramente espacial y no hostil de estar cara a cara.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1728', 'spa', 'comenzar, hacer un comienzo; iniciar una acción o estado, especialmente empresas significativas', 'Originalmente usado para comenzar ofrendas sacrificiales, el término se amplió para significar cualquier tipo de comienzo o inicio. Pablo lo usa dos veces para resaltar el contraste entre comenzar y continuar. Los gálatas comenzaron por el Espíritu pero neciamente trataron de completar por la carne (Gál 3:3). Dios, quien comenzó una buena obra en los filipenses, la completará hasta el día de Cristo (Fil 1:6). Los participios aoristos enfatizan el momento decisivo de la iniciación, preparando la ironía o confianza de lo que sigue.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1729', 'spa', 'necesitado, carente, en necesidad; falto o privado de los recursos necesarios', 'Este adjetivo describe a alguien que está en necesidad o carece de lo indispensable. Hechos 4:34 lo emplea para describir el modelo económico de la iglesia primitiva: ''No había entre ellos ningún necesitado''. El término indica carencia o privación material. En textos clásicos podía significar falto de algo específico o generalmente necesitado. Lucas subraya la eliminación total de la pobreza en la iglesia de Jerusalén mediante una generosidad radical y la práctica de compartir los bienes comunitariamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1730', 'spa', 'evidencia, prueba, señal; aquello que demuestra o hace patente algo', 'Este sustantivo designa una evidencia o prueba, algo que demuestra una verdad o realidad. En 2 Tesalonicenses 1:5, Pablo llama a la paciente perseverancia de los creyentes bajo persecución «señal manifiesta del justo juicio de Dios». Su sufrimiento prueba la justicia divina, tanto al honrar la fidelidad de ellos como al juzgar a sus perseguidores. En el uso clásico, ἔνδειγμα se empleaba para denotar muestras o evidencias de buena voluntad o verdad. Pablo transforma el sufrimiento en valor probatorio que revela los propósitos divinos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1731', 'spa', 'Mostrar, demostrar, exhibir — poner de manifiesto o probar abiertamente una cualidad, ya sea la ira y misericordia de Dios o la fidelidad humana. El v', 'Mostrar, demostrar, exhibir — poner de manifiesto o probar abiertamente una cualidad, ya sea la ira y misericordia de Dios o la fidelidad humana. El verbo ἐνδείκνυμι (endeiknymi) significa mostrar, demostrar o exhibir públicamente para que otros lo vean. Constituye un término paulino clave para la revelación deliberada de los atributos divinos: Dios ''demuestra'' su ira contra el pecado (Ro 9:17, 22), ''muestra'' las inmensas riquezas de su gracia hacia los creyentes (Ef 2:7) y ''exhibió'' su perfecta paciencia al salvar a Pablo como ejemplo (1 Ti 1:16). Los sujetos humanos igualmente ''muestran'' su amor, fidelidad o buena conducta ante los demás (2 Co 8:24; Tit 2:10; 3:2; Heb 6:10-11). Ro 2:15 lo usa para los gentiles que ''muestran'' la obra de la ley escrita en sus corazones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1732', 'spa', 'Demostración, prueba, evidencia; exhibición visible que establece algo como verdadero', 'Este sustantivo designa una manifestación concreta que hace algo evidente o demostrable ante otros. Pablo lo emplea dos veces en Romanos 3:25-26 para describir la muerte sacrificial de Cristo como ''demostración'' de la justicia de Dios, no una mera afirmación sino una exhibición pública de justicia. En 2 Corintios 8:24 se insta a los corintios a mostrar prueba de su amor ante las iglesias. Filipenses 1:28 presenta la resistencia de los adversarios como evidencia de su destrucción. Cada uso exige que la prueba sea visible ante testigos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1733', 'spa', 'Once; el número cardinal, usado en el NT para designar al grupo apostólico tras la partida de Judas.', 'El numeral indeclinable ''once'' aparece en el NT exclusivamente como designación del círculo apostólico entre la traición de Judas y la elección de Matías. Funciona casi como un título — ''los Once'' — señalando una ausencia conmovedora entre los Doce. El Cristo resucitado se aparece a los Once (Marcos 16:14; Mateo 28:16), las mujeres informan del sepulcro vacío a los Once (Lucas 24:9, 33), y el grupo se restaura a doce cuando Matías es contado con los Once (Hechos 1:26). El peso teológico no reside en el número en sí, sino en la ausencia que implica: la brecha dejada por la traición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1734', 'spa', 'Undécimo, número ordinal de once; indica la undécima hora o la undécima piedra de fundamento', 'El adjetivo ἑνδέκατος es el número ordinal correspondiente a once, usado para indicar secuencia o posición. En la parábola de Jesús sobre los obreros de la viña, la «undécima hora» representa la última hora de una jornada laboral de doce horas: casi demasiado tarde, pero aún a tiempo para la contratación y la gracia. En la Nueva Jerusalén de Apocalipsis, la undécima piedra de fundamento marca su lugar en la belleza ordenada de la ciudad eterna. El número en sí conlleva un sentido de tardanza o cercanía al final.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1735', 'spa', 'es posible, es admisible; algo que puede suceder o es permisible', 'Este verbo impersonal significa «es posible» o «es admisible», indicando que algo puede ocurrir o está permitido. En Lucas 13:33, Jesús dice: «No es posible que un profeta muera fuera de Jerusalén», expresando la trágica inevitabilidad de que los profetas perezcan en la ciudad santa. El término transmite tanto posibilidad lógica como conveniencia contextual. En el uso clásico podía significar aceptar, creer o permitir. Jesús lo emplea para expresar el patrón trágico del rechazo de Jerusalén hacia los mensajeros de Dios, caminando conscientemente hacia la cruz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1736', 'spa', 'Estar en casa, habitar en; residir en el lugar propio, especialmente el cuerpo como morada temporal', 'El verbo ἐνδημέω (ἐν + δῆμος, «en casa entre los suyos») significa estar en casa, habitar o residir en un lugar. Pablo lo emplea como contrapunto de ἐκδημέω («estar fuera de casa»), creando una metáfora espacial para la doble ubicación del creyente: en casa en el cuerpo pero lejos del Señor, o fuera del cuerpo y en casa con el Señor. El verbo presenta la vida corporal como una residencia temporal, cuyo verdadero hogar se encuentra en otra parte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1737', 'spa', 'vestir, ataviarse; poner vestiduras a alguien, a menudo en contextos ceremoniales o habituales', 'Esta forma describe vestir a otra persona o a uno mismo. Los soldados romanos vistieron a Jesús de púrpura burlonamente antes de crucificarlo (Marcos 15:17). El rico de la parábola de Jesús se vestía habitualmente de púrpura y lino fino (Lucas 16:19), con el tiempo imperfecto enfatizando su lujo acostumbrado. Aunque el acto es neutral, el contexto determina si es burla, costumbre u honor. La voz media puede enfatizar el interés personal en la vestimenta, aunque el uso varía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1738', 'spa', 'justo, correcto, merecido; conforme a la justicia o lo que es legal y moralmente apropiado', 'La palabra afirma lo que concuerda con la justicia y el derecho. Pablo reconoce que la condenación podría parecer justa dadas ciertas premisas, aunque rechaza esas premisas (Rom 3:8). El autor de Hebreos declara que cada transgresión bajo el antiguo pacto recibió su justa retribución (Heb 2:2). El término combina legitimidad legal con rectitud moral: lo que no solo es lícito sino justamente merecido. El uso clásico incluía contextos judiciales y descripciones de ciudades o acciones justas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1739', 'spa', 'estructura, construcción, material de edificación; el acto de construir o lo edificado como parte de una estructura', 'Este sustantivo poco frecuente designa una estructura o construcción, específicamente algo edificado como parte de un conjunto arquitectónico mayor. Apocalipsis 21:18 lo emplea para describir la construcción o el material del muro de la Nueva Jerusalén. El léxico señala que también puede significar dique, rompeolas o estructura empotrada. Juan usa lenguaje arquitectónico para describir realidades celestiales: la construcción de jaspe simboliza pureza, fortaleza y gloria divina. El término subraya la naturaleza artesanal e intencional de la ciudad eterna de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1740', 'spa', 'ser glorificado, hecho glorioso; recibir honor y manifestar gloria, especialmente gloria divina', 'Este verbo pasivo describe recibir gloria o ser hecho glorioso, particularmente en contextos escatológicos. Pablo ora para que el Señor Jesús sea glorificado en los tesalonicenses, y ellos en él (2 Tes 1:10, 12). La glorificación recíproca señala el honor mutuo entre Cristo y su pueblo cuando él regrese. La voz pasiva enfatiza que la glorificación viene de la acción de Dios, no de la autopromoción. El término aparece en contextos de adoración y manifestación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1741', 'spa', 'Glorioso, espléndido, honrado; que posee o refleja honor, distinción o esplendor notable.', 'Adjetivo derivado de δόξα (''gloria''), que describe a personas o cosas que poseen o reflejan honor, esplendor o distinción. En Lucas 7:25 caracteriza las vestimentas finas de quienes habitan en palacios reales. Lucas 13:17 relata que la multitud se regocijaba por todas las ''cosas gloriosas'' que Jesús realizaba. Pablo lo emplea con amarga ironía en 1 Corintios 4:10: ''vosotros sois honrados, nosotros despreciados''. Efesios 5:27 presenta a la iglesia como la novia de Cristo: ''gloriosa, sin mancha ni arruga'', apuntando a su perfección escatológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1742', 'spa', 'Vestido, vestimenta; prenda exterior de vestir, usada literal y metafóricamente de la apariencia externa.', 'La palabra griega estándar para una prenda exterior o pieza de vestir, que aparece en contextos que van desde lo cotidiano hasta lo simbólico. Jesús enseña a no preocuparse por la vestimenta (Mateo 6:25, 28) y advierte sobre falsos profetas que vienen ''con vestidos de ovejas'' (Mateo 7:15), metáfora que ha penetrado en muchos idiomas. El término describe la distintiva vestidura de pelo de camello de Juan el Bautista (Mateo 3:4), al invitado a la boda que carece de la vestimenta apropiada (Mateo 22:11-12), y el vestido blanco resplandeciente del ángel en la resurrección (Mateo 28:3). El español ''vestido'' lo traduce como ropa corriente, y es el contexto el que aporta cualquier significado más profundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1743', 'spa', 'Fortalecer, capacitar con poder (activo); ser fortalecido, crecer en fuerza (pasivo/medio), especialmente por habilitación divina.', 'Formado a partir de ἐν (''en'') y δυναμόω (''hacer poderoso''), el verbo ἐνδυναμόω pertenece a la familia léxica de δύναμις y siempre transmite la idea de poder infundido o en crecimiento. Sus dos voces dividen el significado en perspectivas complementarias. En la voz pasiva o media, una persona es fortalecida o crece en vigor: Saulo ''iba fortaleciéndose cada vez más'' tras su conversión (Hch 9:22), Abraham ''se fortaleció en la fe'' (Ro 4:20), y Pablo exhorta a los creyentes a ''fortalecerse en el Señor y en el poder de su fuerza'' (Ef 6:10). En la voz activa, Cristo o Dios es el agente que fortalece: Pablo agradece a ''Cristo Jesús, que me fortaleció'' (1 Ti 1:12), confiesa ''todo lo puedo en aquel que me fortalece'' (Fil 4:13), y declara ''el Señor estuvo a mi lado y me fortaleció'' (2 Ti 4:17). El patrón teológico es constante: poder divino fluyendo hacia la debilidad humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1744', 'spa', 'infiltrarse, introducirse furtivamente; entrar sigilosamente y de manera gradual', 'Este verbo significa entrar con sigilo o infiltrarse gradualmente, con frecuencia con connotaciones negativas. En 2 Timoteo 3:6, Pablo advierte sobre falsos maestros que «se introducen en las casas» y cautivan a mujeres vulnerables. El término originalmente significaba ponerse ropa, pero desarrolló el sentido de penetrar o entrar subrepticiamente. Pablo lo usa para describir tácticas manipuladoras de infiltración: estos engañadores no se presentan abiertamente, sino que se cuelan en espacios privados donde pueden explotar a los incautos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1745', 'spa', 'acción de vestirse, uso de vestimenta; el proceso o práctica de ponerse ropa', 'Este sustantivo designa el acto de ponerse ropa o la práctica de vestirse con determinadas prendas. 1 Pedro 3:3 lo emplea en la enseñanza sobre la verdadera belleza: las mujeres no deben centrarse en el adorno exterior como peinados elaborados, joyas de oro o ropa fina. El término enfatiza el proceso de vestirse y la atención dedicada a la apariencia externa. Pedro contrasta la decoración superficial con la belleza interior del carácter, redirigiendo el enfoque desde la ἔνδυσις temporal y externa hacia las virtudes internas y duraderas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1746', 'spa', 'Ponerse, vestir, revestirse — vestirse a sí mismo o a otro con ropas, armadura o cualidades espirituales.', 'Ponerse, vestir, revestirse — vestirse a sí mismo o a otro con ropas, armadura o cualidades espirituales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1749', 'spa', 'Emboscada; lugar donde se acecha para atacar, trampa; también estorbo u obstrucción', 'Este término designa una posición oculta donde alguien se apostaba para atacar: una emboscada en contextos militares o de caza. La Septuaginta lo emplea para traducir la palabra hebrea que describe la emboscada táctica de Josué contra Hai. Con el tiempo, su uso se amplió para referirse a cualquier estorbo u obstrucción que impide el avance. Esta doble gama semántica refleja cómo una trampa oculta puede bloquear físicamente el camino de alguien.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1750', 'spa', 'envolver, enrollar; cubrir algo con tela o material, especialmente para sepultura', 'Este verbo significa envolver o enrollar algo en tela, generalmente con fines funerarios. En Marcos 15:46, José de Arimatea envuelve el cuerpo de Jesús en una sábana de lino fino después de bajarlo de la cruz. Se trata de vocabulario sepulcral que describe la preparación reverente de un cuerpo según la costumbre judía. El uso de lino fino indica tanto respeto como premura antes del sábado. En el griego clásico también se empleaba para envolver objetos en tela o, metafóricamente, estar enredado en algo, pero Marcos lo utiliza de forma literal y conmovedora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1751', 'spa', 'estar dentro, existir en el interior; estar presente o contenido dentro de algo', 'Este verbo significa estar dentro de algo o existir en su interior. En Lucas 11:41, Jesús instruye a los fariseos a dar como limosna ''lo que está dentro,'' es decir, lo que tienen a su disposición. El término designa contenidos o posesiones internas. En el uso clásico significaba estar presente en un lugar o contenido en su interior. Jesús contrasta la pureza ritual externa con la generosidad interior: lo que hay dentro de la copa importa más que su exterior. La verdadera pureza implica disponer generosamente de los recursos interiores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1752', 'spa', 'A causa de, por causa de, por amor de — preposición causal que expresa razón o propósito.', 'A causa de, por causa de, por amor de — preposición causal que expresa razón o propósito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1753', 'spa', 'Operación, actividad, poder operante; especialmente de la energía divina o sobrenatural que obra produciendo efectos.', 'Sustantivo que denota poder activo y eficaz — no potencia estática, sino energía que obra efectivamente produciendo resultados. En el Nuevo Testamento aparece casi exclusivamente en las cartas paulinas y se refiere de modo abrumador al poder divino en operación. Pablo habla de ''la operación de la fuerza de su poder'' que resucitó a Cristo de entre los muertos (Efesios 1:19), la ''energía'' que le fue dada para el ministerio apostólico (Efesios 3:7; Colosenses 1:29), y el poder de Cristo ''que le capacita para sujetar a sí mismo todas las cosas'' (Filipenses 3:21). El cuerpo de Cristo crece mediante la ''operación'' de cada miembro individual (Efesios 4:16). El español ''energía'' conserva perfectamente la conexión etimológica con el griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1754', 'spa', 'Obrar, estar activo, operar; especialmente del poder divino o espiritual en acción; también ser eficaz o producir resultados.', 'Obrar, estar activo, operar; especialmente del poder divino o espiritual en acción; también ser eficaz o producir resultados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1756', 'spa', 'Eficaz, activo, poderoso; que produce resultados reales, operativamente potente', 'El adjetivo ἐνεργής (de ἐν + ἔργον, «en acción») describe algo activamente eficaz, operativamente poderoso, que produce resultados concretos. No se refiere a un mero potencial, sino a energía en acción. En el uso bíblico se aplica a una puerta abierta para la misión (1 Co 16:9), a la fe que se vuelve eficaz mediante el conocimiento (Flm 6) y a la palabra de Dios como viva y activa (Heb 4:12). El término subraya la funcionalidad: algo que obra, que cumple su propósito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1758', 'spa', 'Guardar rencor, ser hostil, retener algo contra alguien; oposición o resentimiento sostenido hacia una persona', 'El verbo compuesto ἐνέχω (ἐν + ἔχω, «retener en») significa guardar algo en contra de alguien: albergar rencor, mantener hostilidad o tener a alguien por responsable. Las formas pasiva y media sugieren quedar atrapado o enredado en algo, como en una red o una obligación. El uso bíblico destaca el antagonismo relacional: Herodías guardando rencor contra Juan el Bautista, los escribas acosando a Jesús con preguntas hostiles, y el peligro de quedar sujetos al yugo de la esclavitud. El verbo capta una oposición sostenida y a menudo amarga.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1759', 'spa', 'Aquí, en este lugar; adverbio de ubicación que indica la posición presente del hablante. Un adverbio locativo que significa ''aquí'' o ''en este lugar'', ', 'Aquí, en este lugar; adverbio de ubicación que indica la posición presente del hablante. Un adverbio locativo que significa ''aquí'' o ''en este lugar'', señalando la ubicación física inmediata del hablante. Jesús lo usa después de la resurrección para pedir alimento: ''¿Tenéis aquí algo de comer?'' (Lc 24:41), anclando su presencia corporal resucitada en la realidad tangible. La mujer samaritana pregunta a Jesús sobre sacar agua ''aquí'' en el pozo de Jacob (Jn 4:15-16). En Hch 16:28, Pablo exclama en la cárcel de Filipos que todos los presos siguen ''aquí''. La palabra no lleva peso teológico propio, pero sitúa las narrativas en una inmediatez espacial concreta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1760', 'spa', 'Pensar profundamente, reflexionar, considerar algo detenidamente en la mente', 'Este verbo describe la actividad mental de considerar algo con cuidado y reflexión interior. Aparece en contextos donde alguien medita sobre una situación: José pensando en el embarazo de María, Jesús percibiendo los pensamientos hostiles de los escribas, o Pedro reflexionando sobre su visión. El griego combina ἐν (dentro) con θυμός (mente, espíritu), enfatizando la deliberación interna. Los traductores de diversas lenguas recurren consistentemente a términos como «pensar», «reflexionar» o «meditar», reconociendo que se trata de un trabajo cognitivo profundo, no de una mera percepción superficial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1761', 'spa', 'Pensamiento, reflexión, deliberación interior; el contenido o proceso de ponderar en la mente.', 'Sustantivo formado a partir de ἐν + θυμός (''en el espíritu/mente''), que designa las operaciones internas del pensamiento, aquello que uno da vueltas en el corazón. Jesús percibe las ἐνθυμήσεις de los escribas en Mateo 9:4 y de los fariseos en Mateo 12:25, dejando al descubierto razonamientos hostiles ocultos. Hechos 17:29 lo emplea para los productos de la imaginación artística humana. Hebreos 4:12 declara que la palabra de Dios discierne ''los pensamientos y las intenciones del corazón'', emparejando ἐνθυμήσεων con ἐννοιῶν.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1762', 'spa', 'Estar en; haber, existir (frecuentemente como marcador existencial enfático: ''no hay ni... ni'').', 'Forma contraída de ἔνεστι (''está dentro/presente''), este verbo en el uso neotestamentario funciona principalmente como marcador existencial enfático. Pablo lo emplea de manera memorable en Gálatas 3:28 — ''no hay judío ni griego, no hay esclavo ni libre, no hay varón ni mujer'' — donde el triple ἔνι martilla la disolución de las categorías sociales en Cristo. El mismo sentido existencial aparece en Colosenses 3:11 y 1 Corintios 6:5. El español ''hay'' refleja con claridad esta función existencial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1763', 'spa', 'año — período de doce meses, usado para el cómputo calendárico, los ciclos litúrgicos y la duración temporal. Ἐνιαυτός designa un año completo y conll', 'año — período de doce meses, usado para el cómputo calendárico, los ciclos litúrgicos y la duración temporal. Ἐνιαυτός designa un año completo y conlleva una connotación ligeramente más formal o cíclica que el más común ἔτος. En el griego clásico significaba originalmente ''aniversario'' o ''ciclo'' (de ἐνί + αὐτός, ''que vuelve sobre sí mismo''), y este matiz cíclico persiste en su uso neotestamentario. Hebreos lo emplea repetidamente para el ritual anual del Día de la Expiación — el sumo sacerdote entrando en el Lugar Santísimo ''una vez cada año'' (Heb 9:7, 10:1, 10:3) — donde la repetición anual subraya la insuficiencia que el sacrificio único de Cristo resuelve de una vez por todas. El Evangelio de Juan señala que Caifás era sumo sacerdote ''aquel año'' (Jn 11:49, 51; 18:13), cargando un simple marcador temporal con ironía dramática.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1764', 'spa', 'Estar presente, estar vigente (de tiempos, situaciones); sobrevenir, llegar, ser inminente (de eventos futuros).', 'El verbo ἐνίστημι significa literalmente ''estar en pie dentro'' o ''colocar dentro'', pero en el NT se ha especializado en dos sentidos temporales que juntos enmarcan la comprensión bíblica del tiempo presente e inminente. Con mayor frecuencia, sus formas de participio perfecto (ἐνεστῶσα, ἐνεστῶτος) funcionan adjetivalmente para describir lo ''presente'': la angustia presente (1 Co 7:26), el presente siglo malo (Gá 1:4), las cosas presentes en el gran catálogo retórico de Pablo sobre lo que no puede separarnos del amor de Cristo (Ro 8:38; 1 Co 3:22). Pero en dos pasajes el tiempo futuro introduce un matiz de llegada: ''vendrán tiempos difíciles'' (2 Ti 3:1) y los tesalonicenses alarmados temiendo que ''el día del Señor ha llegado'' (2 Ts 2:2). Aquí ἐνίστημι pasa de presencia estática a irrupción dinámica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1766', 'spa', 'Noveno — numeral ordinal que designa la hora novena (aproximadamente las 3 PM), momento central en los relatos de la crucifixion y en las parabolas. E', 'Noveno — numeral ordinal que designa la hora novena (aproximadamente las 3 PM), momento central en los relatos de la crucifixion y en las parabolas. El adjetivo ἔνατος (enatos) es la forma ordinal de ''nueve'' y aparece en el NT exclusivamente para senalar la hora novena del dia (cerca de las 3 PM segun el computo judio). Sus apariciones mas significativas enmarcan la oscuridad durante la crucifixion: desde la hora sexta la oscuridad cubrio la tierra hasta la hora novena, cuando Jesus clamo (Mt 27:45-46; Mr 15:33-34; Lc 23:44). La parabola de los obreros de la vina menciona a trabajadores contratados a la hora novena (Mt 20:5). La vision de Cornelio y su oracion ocurren tambien a la hora novena (Hch 10:3, 30).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1767', 'spa', 'Nueve; número cardinal entre ocho y diez, usado tanto literalmente como en expresiones que designan un grupo mayor.', 'Número cardinal sencillo que significa ''nueve''. En el Nuevo Testamento aparece exclusivamente en parábolas y dichos de Jesús. Las parábolas de la oveja perdida en Mateo 18 y Lucas 15 hablan de dejar a ''las noventa y nueve'' (literalmente ''las nueve y noventa'') para buscar a la que se extravió. En Lucas 17:17, Jesús pregunta: ''¿No fueron diez los que quedaron limpios? ¿Dónde están los otros nueve?'' Las traducciones a diversos idiomas coinciden de forma notable, reflejando su significado numérico simple y unívoco.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1768', 'spa', 'Noventa (número cardinal).', 'Numeral griego indeclinable que significa noventa, empleado exclusivamente en las parábolas de la oveja perdida. Tanto en Mateo 18:12-13 como en Lucas 15:4-7, el pastor deja a las noventa y nueve en seguridad para buscar a la que se ha extraviado. La única función narrativa de este número en el Nuevo Testamento es dramatizar el valor que Dios otorga a cada individuo: las noventa y nueve ovejas a salvo hacen que el rescate de la única perdida resulte aún más conmovedor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1769', 'spa', 'mudo, sin habla, incapaz de hablar; enmudecido por asombro o impacto', 'Este adjetivo significa sin habla o incapaz de hablar, ya sea por mudez natural o por conmoción. En Hechos 9:7, los compañeros de Pablo permanecen mudos tras escuchar la voz del cielo en el camino a Damasco. En el uso clásico, este término se emparejaba frecuentemente con ''sordo'' para indicar sordomudez, pero también se empleaba para describir un silencio atónito. Lucas lo utiliza para retratar el efecto abrumador del encuentro divino: los hombres quedan enmudecidos ante la teofanía, incapaces de responder a lo que han presenciado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1770', 'spa', 'hacer señas, gesticular, señalar con movimientos; comunicarse de forma no verbal mediante gestos', 'Este verbo significa señalar o comunicarse mediante gestos, típicamente asintiendo o haciendo señas. En Lucas 1:62, la gente hace señas a Zacarías preguntándole cómo quiere que se llame su hijo, ya que había quedado mudo. El término describe la comunicación no verbal impuesta por su incapacidad de hablar. En el uso clásico significaba asentir para señalar o hacer ademanes. Lucas lo emplea para retratar el recurso que la comunidad utilizaba para comunicarse con el sacerdote durante su mudez impuesta por Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1773', 'spa', 'de noche, durante las horas nocturnas; en la noche cuando aún está oscuro, de madrugada', 'Este adverbio significa durante la noche o cuando todavía está oscuro. Marcos 1:35 registra que Jesús se levantó ''muy de madrugada, cuando aún estaba muy oscuro'' para orar en un lugar solitario. El término enfatiza la oscuridad anterior al amanecer, la profundidad de la noche cuando Jesús buscaba comunión con el Padre. En el uso clásico se aplicaba a visitas o actividades nocturnas. Marcos resalta la disciplina de oración de Jesús: sacrificó el sueño para asegurar tiempo sin interrupciones con Dios antes de que las demandas del ministerio se acumularan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1774', 'spa', 'Habitar en, morar dentro de; usado metafóricamente del Espíritu de Dios, la palabra de Cristo o la fe que reside en una persona o comunidad.', 'Lleva el significado central de habitar o hacer morada dentro de un lugar o persona. En el Nuevo Testamento se emplea exclusivamente en sentido espiritual y metafórico: el Espíritu de Dios morando en los creyentes (Ro 8:11), Dios habitando entre su pueblo (2 Co 6:16), la palabra de Cristo morando en abundancia en la comunidad (Col 3:16), y la fe sincera residiendo primero en una abuela y una madre antes de transmitirse a Timoteo (2 Ti 1:5, 14). Evoca una presencia interior estable y transformadora, no una visita pasajera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1777', 'spa', 'Culpable, reo, merecedor de castigo; tambien sujeto a o sometido bajo un poder o condicion. Adjetivo juridico que resuena en el Sermon del Monte como ', 'Culpable, reo, merecedor de castigo; tambien sujeto a o sometido bajo un poder o condicion. Adjetivo juridico que resuena en el Sermon del Monte como un golpe de mazo en un tribunal. En Mateo 5:21-22, Jesus eleva la gravedad: la ira hace al hombre ''reo'' ante el juicio, el insulto ''culpable'' ante el concilio, y el desprecio ''merecedor'' de la Gehena. En el juicio de Jesus, el Sanedrin lo declara ''reo de muerte'' (Mt 26:66; Mr 14:64). Un uso distintivo en Hebreos 2:15 desplaza el significado hacia la sujecion: quienes por temor a la muerte estaban ''sujetos'' a servidumbre perpetua, pasando de la culpa judicial al cautiverio existencial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1778', 'spa', 'Mandamientos, preceptos; regulaciones de origen humano presentadas como si tuvieran autoridad divina', 'El sustantivo ἔνταλμα designa un mandamiento o precepto, sinónimo de ἐντολή, pero en el uso neotestamentario se aplica específicamente a tradiciones humanas elevadas indebidamente a rango de autoridad divina. Jesús cita la denuncia de Isaías contra quienes «enseñan como doctrinas mandamientos de hombres» (Mt 15:9; Mr 7:7), y Pablo advierte contra regulaciones como «No toques, no pruebes» (Col 2:22). La palabra conlleva un matiz peyorativo en el contexto bíblico: son reglas inventadas por hombres que se disfrazan de ley de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1781', 'spa', 'Mandar, ordenar, dar órdenes con autoridad; usado en voz media para emitir directivas. Ἐντέλλομαι (voz media de ἐντέλλω) porta el peso del mandato aut', 'Mandar, ordenar, dar órdenes con autoridad; usado en voz media para emitir directivas. Ἐντέλλομαι (voz media de ἐντέλλω) porta el peso del mandato autoritativo. En el NT aparece cuando Dios, Jesús o Moisés emiten directivas vinculantes. Satanás cita el Salmo 91 — ''A sus ángeles mandará acerca de ti'' (Mt 4:6; Lc 4:10) — y Jesús instruye a sus discípulos a enseñar todo lo que él ha mandado (Mt 28:20). La palabra también abarca mandamientos mosaicos citados en debates legales (Mt 19:7; Mc 10:3). A diferencia de verbos más débiles de petición o solicitud, ἐντέλλομαι implica una autoridad que espera obediencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1782', 'spa', 'De aqui, desde este lugar; tambien usado distributivamente para indicar ''de un lado... del otro lado''. Adverbio espacial que significa ''de aqui'' o ''de', 'De aqui, desde este lugar; tambien usado distributivamente para indicar ''de un lado... del otro lado''. Adverbio espacial que significa ''de aqui'' o ''desde este lugar'', empleado frecuentemente en mandatos de partida o reubicacion. Jesus le dice al diablo ''vete de aqui'' (Lc 4:9), ordena a sus discipulos ''levantaos, vamonos de aqui'' (Jn 14:31), y manda a los mercaderes ''quitad esto de aqui'' (Jn 2:16). Un uso distributivo especializado aparece en Juan 19:18, donde dos ladrones son crucificados ''de un lado y del otro'' de Jesus, capturando la disposicion espacial simetrica que distingue este sentido del simple ''de aqui''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1784', 'spa', 'Honrado, estimado, precioso; dicho de personas tenidas en alta estima o de cosas consideradas valiosas y selectas.', 'Adjetivo derivado de τιμή (''honor, valor'') que describe a alguien o algo tenido en gran estima. Puede aplicarse a personas, como el siervo apreciado del centurión (Lucas 7:2) o los líderes cristianos que merecen reconocimiento especial (Filipenses 2:29), y también a cosas, como la piedra viva escogida y preciosa que es Cristo (1 Pedro 2:4, 6). La parábola de Jesús sobre elegir el puesto más honroso en un banquete (Lucas 14:8) resalta la dimensión social del término. Abarca tanto la preciosidad intrínseca como el honor reconocido socialmente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1785', 'spa', 'Mandamiento, precepto — directiva autoritativa, especialmente la ley divina', 'El sustantivo femenino ἐντολή (''mandamiento, precepto'') designa una directiva autoritativa, ya sea divina o humana. Sus 67 apariciones neotestamentarias conciernen abrumadoramente a los mandatos de Dios: los mandamientos mosaicos debatidos en los Evangelios (''¿cuál es el gran mandamiento?'', Mt 22:36), el ''mandamiento nuevo'' del amor que Jesús da (Jn 13:34), y las exhortaciones apostólicas a guardar los mandamientos de Dios (1 Jn 2:3-4; 3:22-24). A diferencia de νόμος (''ley'' como sistema), ἐντολή destaca el precepto individual: la directiva concreta y específica. No presenta evidencia de polisemia en el corpus.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1786', 'spa', 'local, del lugar; residentes nativos en contraposición a forasteros o extranjeros', 'Este adjetivo describe a los residentes locales o personas originarias de un lugar determinado, en contraste con los forasteros o visitantes. En Hechos 21:12, tanto «nosotros» (los compañeros de viaje de Pablo) como los residentes del lugar le suplican que no suba a Jerusalén. El término distingue a los habitantes nativos de los visitantes. En el uso clásico se empleaba para costumbres locales, monedas, residentes y guerras civiles (en oposición a conflictos extranjeros). Lucas resalta la unanimidad de preocupación entre ambos grupos: locales y visitantes por igual ruegan a Pablo que evite el peligro que le aguarda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1788', 'spa', 'Volver a alguien hacia adentro en vergüenza o deferencia; ''avergonzar, amonestar'' o ''respetar, reverenciar'' (voz media/pasiva).', 'De ἐν (en) + τρέπω (volver), este verbo significa literalmente ''volver a alguien hacia adentro'', y sus dos sentidos fluyen naturalmente de esa imagen raíz. En voz media describe un volverse hacia alguien con deferencia: ''respetarán a mi hijo'', dice el dueño de la viña en la parábola de Jesús (Mt 21:37; Mc 12:6; Lc 20:13). En su uso activo o causativo, significa hacer que alguien se vuelva hacia adentro de un modo muy distinto: provocarle vergüenza. Pablo lo emplea con delicadeza pastoral: ''No escribo esto para avergonzaros'' (1 Co 4:14). El español refleja elegantemente esta dualidad, usando ''respetar'' para la reverencia y ''avergonzar'' para la vergüenza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1789', 'spa', 'ser nutrido en, criado en; formarse o educarse en algo mediante exposición continua', 'Este verbo en voz pasiva o media significa ser nutrido, criado o formado en algo. Primera Timoteo 4:6 anima a Timoteo a «nutrirse en las palabras de la fe y de la buena doctrina». El término sugiere una formación continua mediante exposición sostenida. En el uso clásico incluía ser criado en ciertas prácticas o educado en enseñanzas particulares. Pablo lo emplea para describir la formación constante de Timoteo mediante la sana doctrina, contrastando este alimento saludable con los mitos venenosos que debe rechazar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1790', 'spa', 'Tembloroso, que tiembla físicamente de temor o reverencia', 'Adjetivo que describe a alguien que tiembla físicamente, generalmente como respuesta al encuentro con la presencia divina abrumadora. La palabra combina ἐν (en) con τρόμος (temblor), capturando una reacción corporal de temor. Las tres apariciones en el Nuevo Testamento ocurren en momentos de encuentro con lo divino: Moisés ante la zarza ardiente, el carcelero de Filipos tras el terremoto y la apertura sobrenatural de la prisión, y los israelitas en el Sinaí. Refleja tanto la manifestación física como su raíz emocional: terror reverente ante lo santo e imponente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1792', 'spa', 'deleitarse en, entregarse a; disfrutar algo con autocomplacencia o exceso', 'Este verbo significa deleitarse o gozar lujosamente de algo, a menudo con connotaciones negativas de exceso o burla. Segunda Pedro 2:13 condena a los falsos maestros que «se deleitan en sus engaños mientras participan de vuestras comidas». El término sugiere un placer autocomplaciente, a veces a costa de otros. En el uso clásico incluía gozar de privilegios, regocijarse en la desgracia ajena o tratar las cosas con desprecio. Pedro retrata a hedonistas desvergonzados que se recrean en su propio engaño incluso durante las comidas sagradas de comunión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1793', 'spa', 'Interceder, apelar, suplicar; acudir ante alguien con autoridad en favor o en contra de otro.', 'Verbo que originalmente significaba encontrarse con alguien y que desarrolló el sentido especializado de hacer una apelación formal o intercesión. En el Nuevo Testamento abarca tanto la intercesión positiva —el Espíritu intercediendo por los santos (Romanos 8:27), Cristo intercediendo a la diestra de Dios (Romanos 8:34, Hebreos 7:25)— como la petición negativa, cuando los líderes judíos apelaron ante Festo contra Pablo (Hechos 25:24) o cuando Elías clamó a Dios contra Israel (Romanos 11:2). El término marca consistentemente un acercamiento solemne a una figura de autoridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1794', 'spa', 'Envolver, enrollar; cubrir algo completamente con tela, especialmente en la preparación para la sepultura', 'El verbo ἐντυλίσσω (de ἐν + τυλίσσω, «enrollar») significa envolver o enrollar algo en tela. En el Nuevo Testamento aparece exclusivamente en contextos funerarios, describiendo cómo fue envuelto el cuerpo de Jesús en lienzo tras la crucifixión. Envolver el cadáver era una práctica esencial del rito funerario judío, preservando la dignidad y conteniendo la descomposición. El verbo capta tanto el cuidado tierno de la preparación para la sepultura como la finalidad de la muerte: el cuerpo envuelto, cubierto, entregado al sepulcro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1795', 'spa', 'grabar, tallar, imprimir; inscribir letras o diseños en una superficie dura', 'Este verbo significa grabar o tallar en una superficie, generalmente piedra o metal. Segunda Corintios 3:7 habla de la ley «grabada en piedras», contrastando la antigua alianza escrita en tablas con la nueva alianza escrita en corazones humanos. El participio perfecto pasivo enfatiza el estado completado y permanente del grabado. En el uso clásico incluía tallar en monumentos y moldear en relieve. Pablo emplea la permanencia física del grabado en piedra para resaltar una permanencia mayor: la inscripción interna del Espíritu en corazones transformados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1796', 'spa', 'ultrajar, afrentar, tratar con desprecio; mostrar falta de respeto o desdén hacia alguien o algo sagrado', 'Este verbo significa insultar o tratar con ultraje y desprecio, especialmente en relación con cosas sagradas. Hebreos 10:29 advierte del severo castigo para quienes «ultrajen al Espíritu de gracia». Se trata de un rechazo voluntario y arrogante de la oferta misericordiosa de Dios. En el uso clásico incluía insultar a personas, burlarse de ellas en sus circunstancias o tratar las leyes con desprecio. El autor de Hebreos emplea el lenguaje más enérgico para describir el pisotear la sangre de Cristo e insultar al Espíritu: una apostasía que merece un juicio temible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1798', 'spa', 'sueño, visión durante el dormir; experiencia onírica frecuentemente con significado profético', 'Este sustantivo designa un sueño o visión experimentada durante el dormir. Hechos 2:17 cita la profecía de Joel que anuncia que en los últimos días «vuestros jóvenes verán visiones, y vuestros ancianos soñarán sueños». El término denota visiones nocturnas concedidas por Dios como medio de revelación. En el uso clásico a veces se distinguía entre sueños proféticos significativos y sueños ordinarios sin importancia, aunque esta distinción no se mantuvo de manera constante. Pedro aplica la promesa de Joel al día de Pentecostés: el Espíritu derramado trae comunicación divina a través de sueños y visiones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1799', 'spa', 'Delante de, en presencia de, ante los ojos de — preposición impropia (con genitivo) de posición relacional', 'Ἐνώπιον funciona como preposición impropia que rige genitivo para expresar ''delante de, en presencia de, a los ojos de''. Su distribución es predominantemente lucana y joánica: Lucas y Hechos concentran gran parte de sus apariciones, y Apocalipsis lo emplea extensamente en escenas ante el trono divino. El vocablo porta un matiz marcadamente personal: no meramente espacial ''enfrente de'', sino relacional ''bajo la mirada de'', lo que lo convierte en el término preferido para estar ante Dios (Lc 1:15; Ap 4:5), ser aceptable a los ojos de Dios (Hch 4:19) y rendir cuentas ante un juez.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1800', 'spa', 'Enós, hijo de Set, nieto de Adán; tercera generación desde Adán en la genealogía de Lucas', 'Este es el nombre propio Enós, que se refiere al hijo de Set y nieto de Adán mencionado en Génesis 4:26. Lucas 3:38 lo incluye en la genealogía de Jesús, trazando el linaje hasta Adán y en última instancia hasta Dios. El nombre proviene del hebreo אֱנוֹשׁ que significa «hombre» o «mortal». Génesis señala que en los días de Enós los hombres comenzaron a invocar el nombre del Señor. La inclusión de estos nombres ancestrales por parte de Lucas fundamenta a Jesús en toda la historia humana desde la creación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1801', 'spa', 'prestar oído, escuchar atentamente; oír con intención y receptividad', 'Este verbo significa prestar oído o escuchar con atención, derivado de la palabra para «oído». En Hechos 2:14, Pedro ordena a la multitud: «escuchad mis palabras» al iniciar su sermón de Pentecostés. El término enfatiza una escucha intencional y atenta que va más allá del mero oír. En la LXX se emplea para obedecer la voz de Dios. Pedro exige atención concentrada para interpretar los asombrosos acontecimientos de Pentecostés. El imperativo demanda más que una audición pasiva: una atención receptiva y obediente a la proclamación apostólica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1802', 'spa', 'Enoc, el séptimo desde Adán, que caminó con Dios y fue llevado sin ver la muerte', 'Nombre propio del patriarca antediluviano Enoc (hebreo חֲנוֹךְ), que aparece en dos contextos clave del Nuevo Testamento. La genealogía de Lucas traza el linaje de Jesús a través de Enoc hasta Adán, mientras que Hebreos lo celebra como ejemplo paradigmático de fe que agradó a Dios, señalando que «fue trasladado para no ver la muerte» (He 11:5, citando Gn 5:24). Judas hace referencia a la tradición de la profecía de Enoc sobre el juicio divino. La transliteración griega Ἐνώχ mantiene una continuidad reconocible con el original hebreo a través de las diversas tradiciones de traducción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1803', 'spa', 'seis — el número cardinal entre cinco y siete. Ἕξ es el número cardinal griego indeclinable seis, que aparece 13 veces en el Nuevo Testamento. Sus apa', 'seis — el número cardinal entre cinco y siete. Ἕξ es el número cardinal griego indeclinable seis, que aparece 13 veces en el Nuevo Testamento. Sus apariciones abarcan contextos narrativos y apocalípticos por igual: las seis tinajas de piedra en Caná (Jn 2:6), la hora sexta como marcador temporal (Jn 4:6), los seis días antes de la Pascua (Jn 12:1) y los seis meses de embarazo de Elisabet (Lc 1:26, 36). En los relatos de la Transfiguración, ''después de seis días'' enmarca la teofanía en el monte (Mt 17:1, Mc 9:2). Santiago invoca los tres años y medio de la sequía de Elías (Stg 5:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1805', 'spa', 'Redimir, rescatar, comprar de vuelta; en voz media, aprovechar al máximo (el tiempo o la oportunidad).', 'Verbo compuesto de ἐκ (''fuera de'') y ἀγοράζω (''comprar en el mercado''), que evoca la imagen vívida de adquirir la libertad de alguien sacándolo de la esclavitud o servidumbre. Pablo lo emplea con gran fuerza en Gálatas 3:13 y 4:5 para describir a Cristo redimiendo a los creyentes de la maldición de la Ley. En Efesios 5:16 y Colosenses 4:5, la forma en voz media ''redimiendo el tiempo'' desplaza la metáfora hacia el aprovechamiento sabio de cada oportunidad, como quien se apresura a obtener una ganga antes de que desaparezca.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1806', 'spa', 'sacar, conducir afuera — llevar a alguien desde un lugar cerrado hacia el exterior, frecuentemente con implicación de liberación. Ἐξάγω combina el pre', 'sacar, conducir afuera — llevar a alguien desde un lugar cerrado hacia el exterior, frecuentemente con implicación de liberación. Ἐξάγω combina el prefijo ἐξ- (''fuera de'') con ἄγω (''conducir'') para expresar la acción de sacar a alguien de un encierro, cautiverio o espacio cerrado. Sus 12 apariciones neotestamentarias portan una fuerte resonancia teológica: Dios sacando a Israel de Egipto (Hch 7:36, 13:17), un ángel liberando a los apóstoles de la cárcel (Hch 5:19) y los soldados sacando a Jesús para la crucifixión (Mc 15:20). El verbo también aparece en la tierna escena de Jesús conduciendo a sus discípulos hacia Betania antes de su ascensión (Lc 24:50).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1807', 'spa', 'Rescatar, librar; arrancar, sacar — extracción de un peligro o remoción física forzada.', 'El verbo ἐξαιρέω (ἐκ + αἱρέω, ''sacar'') se divide en dos sentidos marcadamente distintos en el Nuevo Testamento. En voz media funciona como un poderoso verbo de rescate: Dios ''libró'' a José de todas sus aflicciones (Hch 7:10), descendió para ''rescatar'' a Israel de Egipto (Hch 7:34) y envió un ángel para ''librar'' a Pedro de la cárcel (Hch 12:11). En voz activa con objetos físicos, adquiere una literalidad visceral: Jesús ordena que si tu ojo te hace pecar, ''sácatelo'' (Mt 5:29; 18:9). El español refleja esta división con precisión: ''librar/libró'' para el rescate frente a ''sácalo'' para la extracción física, mostrando que ambos sentidos ocupan territorios conceptuales diferentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1808', 'spa', 'quitar, remover, expulsar; sacar a alguien o algo de un lugar con fuerza o finalidad', 'Este verbo significa quitar o remover, frecuentemente con fuerza o carácter definitivo. Primera de Corintios 5:13 ordena a la iglesia «quitad de entre vosotros a ese malvado», citando la fórmula de Deuteronomio para purgar el mal de la comunidad. El uso clásico incluía levantar cosas o elevar a alguien en dignidad, pero también remover o expulsar. Pablo aplica el lenguaje de pureza del pacto a la disciplina eclesiástica: así como Israel expulsaba a los malhechores para preservar la santidad, la iglesia debe remover a la persona inmoral impenitente para proteger la pureza de la comunidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1809', 'spa', 'demandar, pedir a alguien de otro; solicitar la entrega o liberación de una persona', 'Este verbo significa demandar a alguien de otro o pedir su entrega. Lucas 22:31 registra la advertencia de Jesús a Pedro: «Satanás os ha pedido para zarandearos como a trigo». El término sugiere una petición urgente e insistente, frecuentemente de un superior ante otro. El uso clásico incluía exigir criminales para castigo o pedir en matrimonio. Jesús revela el conflicto cósmico: Satanás ha solicitado cribar a los discípulos. El verbo implica una demanda legal o autoritativa, destacando la guerra espiritual detrás de la inminente negación de Pedro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1810', 'spa', 'De repente, inesperadamente; denota un suceso que ocurre sin aviso ni preparación.', 'Adverbio que expresa una ocurrencia abrupta e imprevista. Cada uso en el Nuevo Testamento conlleva una nota de sorpresa dramática: la hueste celestial apareciendo de repente ante los pastores (Lucas 2:13), un espíritu apoderándose de un muchacho sin aviso (Lucas 9:39), una luz cegadora del cielo resplandeciendo alrededor de Saulo en el camino a Damasco (Hechos 9:3; 22:6) y la advertencia de Jesús sobre el regreso repentino del señor (Marcos 13:36). La palabra marca consistentemente la irrupción divina en la experiencia humana ordinaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1811', 'spa', 'seguir de cerca, perseguir; adherirse con lealtad continua a una persona o enseñanza', 'El verbo compuesto ἐξακολουθέω (ἐκ + ἀκολουθέω, «seguir») significa seguir de cerca, ir tras alguien o adherirse a algo con determinación. En su uso bíblico abarca tanto el seguimiento físico como la adhesión metafórica a enseñanzas o ejemplos. En 2 Pedro describe tanto el seguimiento positivo (el testimonio apostólico como testigos oculares) como el negativo (herejías destructivas, el camino de Balaam). El prefijo ἐκ intensifica el sentido: no se trata de una asociación casual, sino de una adhesión comprometida y perseverante hasta el final.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1813', 'spa', 'Borrar, enjugar, cancelar; obliterar algo escrito o eliminar lágrimas y sufrimiento.', 'Combina el prefijo ἐξ- (''fuera, lejos'') con ἀλείφω (''ungir, untar''), produciendo la idea central de limpiar o borrar algo hasta hacerlo desaparecer. En el Nuevo Testamento tiene dos aplicaciones vívidas: borrar un registro de culpa o un nombre —cancelar pecados (Hechos 3:19), anular el acta de decretos (Colosenses 2:14), amenazar con borrar un nombre del libro de la vida (Apocalipsis 3:5)— y la tierna imagen de Dios enjugando toda lágrima (Apocalipsis 7:17; 21:4). Abarca desde la cancelación legal hasta el consuelo compasivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1814', 'spa', 'saltar, brincar; moverse repentinamente hacia arriba con energía y gozo', 'Este verbo significa saltar o brincar hacia arriba, generalmente con gozo o energía repentina. Hechos 3:8 describe al cojo sanado que «saltando, se puso en pie y anduvo» después de que Pedro le ordena caminar en el nombre de Jesús. El término enfatiza un movimiento vigoroso y jubiloso. En el uso clásico incluía saltar desde lugares o peces saltando del agua. Lucas lo emplea para captar la alegría explosiva y la vitalidad física de una sanidad instantánea: un hombre que jamás caminó ahora salta en adoración y alabanza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1815', 'spa', 'resurrección, levantamiento; específicamente la resurrección de entre los muertos a la vida eterna', 'Este sustantivo significa resurrección o levantamiento, específicamente de entre los muertos. Filipenses 3:11 expresa la esperanza de Pablo de «llegar a la resurrección de entre los muertos». El término se usaba en contextos de levantarse de la cama o emigrar, pero en el Nuevo Testamento se refiere primordialmente a la resurrección. Pablo emplea una forma compuesta (ἐξανάστασις en lugar de la simple ἀνάστασις), quizás para enfatizar o distinguir la primera resurrección de los creyentes. Su deseo ardiente es participar del poder y el patrón de la resurrección de Cristo, aunque le cueste todo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1817', 'spa', 'levantar, hacer surgir, suscitar; especialmente engendrar descendencia o un sucesor', 'Verbo causativo que significa hacer que alguien se levante o que algo llegue a existir. En el uso bíblico, con frecuencia lleva el sentido específico de suscitar descendencia o un sucesor, particularmente en el contexto de la ley del levirato, donde un hermano engendra hijos en nombre del hermano fallecido. El compuesto ἐξανίστημι intensifica la raíz «estar de pie» con el prefijo ἐκ, que sugiere un surgir hacia fuera, enfatizando el acto de traer a la existencia. Aparece tanto en la discusión sinóptica sobre la pregunta de los saduceos acerca de la resurrección como en el debate del concilio de Jerusalén sobre los conversos gentiles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1818', 'spa', 'Engañar completamente, seducir por completo; forma intensificada de ἀπατάω que indica un engaño total y devastador.', 'Compuesto intensificado de ἀπατάω (engañar) con el prefijo ἐξ- que transmite exhaustividad, este verbo describe un engaño completo y devastador en sus efectos. Pablo lo usa para describir la estrategia mortal del pecado a través del mandamiento (Ro 7:11), la seducción de Eva por la serpiente (2 Co 11:3) y el peligro de los engañadores de palabras suaves en la iglesia (Ro 16:18). El prefijo eleva el engaño ordinario a algo total: no se trata simplemente de ser desviado, sino de ser completamente embaucado. En 1 Co 3:18, Pablo advierte contra el autoengaño. El verbo subraya que la víctima queda enteramente cautivada por la falsedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1819', 'spa', 'de repente, inesperadamente; sucediendo sin aviso o en un instante', 'Este adverbio significa de repente o inesperadamente, marcando un cambio abrupto o un suceso sorpresivo. Marcos 9:8 lo usa para describir la experiencia de los discípulos en la Transfiguración: «De repente, cuando miraron alrededor, ya no vieron a nadie más que a Jesús solo». El término enfatiza el retorno instantáneo a la normalidad tras la gloriosa teofanía. En el uso clásico y bíblico señala momentos inesperados. Marcos lo emplea para captar el cambio desorientador: un momento Moisés y Elías conversan con Jesús transfigurado; al siguiente, solo queda Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1821', 'spa', 'enviar fuera, despachar — enviar a alguien con propósito, autoridad o comisión. Ἐξαποστέλλω es una forma intensificada de ἀποστέλλω, con el prefijo ἐξ', 'enviar fuera, despachar — enviar a alguien con propósito, autoridad o comisión. Ἐξαποστέλλω es una forma intensificada de ἀποστέλλω, con el prefijo ἐξ- (''fuera'') reforzando la noción de envío. Las 13 apariciones neotestamentarias llevan el sentido de despachar a alguien (o algo) con propósito deliberado. Lucas lo usa con mayor frecuencia: Dios despide vacíos a los ricos (Lc 1:53), un dueño de viña envía siervos a cobrar lo suyo (Lc 20:10-11) y la iglesia primitiva envía a Bernabé y Pablo en misión (Hch 11:22, 12:11, 22:21). El peso teológico es más claro en Gálatas 4:4-6, donde Dios ''envió'' a su Hijo y luego ''envió'' al Espíritu — el doble uso subrayando la iniciativa divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1823', 'spa', 'relampaguear, resplandecer, deslumbrar; brillar con fulgor como un relámpago', 'Este verbo significa relampaguear o resplandecer como un rayo, brillando con una radiancia deslumbrante. Lucas 9:29 lo emplea para describir la vestidura de Jesús durante la Transfiguración, que se volvió «resplandeciente de blancura». El término evoca el destello brillante del relámpago. En el uso clásico se aplicaba a la luz intensa del sol. Lucas utiliza la imagen del rayo para transmitir la radiancia sobrenatural de la apariencia transfigurada de Jesús: sus vestiduras resplandecen con gloria divina, anticipando el brillo de su resurrección y su esplendor eterno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1824', 'spa', 'Inmediatamente, al instante, enseguida; adverbio temporal que marca una acción súbita o pronta.', 'Derivado de ἐξ αὐτῆς (ὥρας) (''desde esa misma hora/momento''), este adverbio marca una acción rápida y sin vacilación. Aparece predominantemente en Hechos, donde Lucas lo emplea para transmitir urgencia narrativa: Cornelio envía a buscar a Pedro ''enseguida'' (Hch 10:33), los hombres de Cesarea llegan ''inmediatamente'' (Hch 11:11), el tribuno baja con soldados ''al instante'' (Hch 21:32), y Claudio Lisias despacha a Pablo de noche ''enseguida'' (Hch 23:30). En Marcos 6:25, la hija de Herodías entra ''inmediatamente'' con su macabra petición. El adverbio subraya la ausencia total de demora entre la decisión y la acción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1826', 'spa', 'Salir, partir, abandonar un lugar; movimiento deliberado de salida.', 'Verbo compuesto de ἐκ (''fuera'') y εἶμι (''ir''), empleado exclusivamente en Hechos para describir la partida física de un lugar. Aparece cuando Pablo y Bernabé salen de la sinagoga (Hechos 13:42), cuando los acompañantes parten hacia Atenas (17:15) y cuando Pablo prolonga su discurso de despedida antes de partir (20:7). El vocablo transmite un desplazamiento deliberado y con propósito desde una reunión o lugar, diferente del mero deambular sin rumbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1827', 'spa', 'Refutar categóricamente, convencer plenamente de culpa; demostrar que alguien está equivocado sin lugar a dudas', 'Forma intensificada del verbo «convencer de culpa», este término significa refutar a alguien por completo o demostrar públicamente su error en un debate. Los autores clásicos lo usan para desenmascarar los errores de alguien ante la asamblea o para probar su culpabilidad. Puede llevar doble acusativo (la persona y el cargo), como en «convencer a alguien de ser incapaz». La voz pasiva aparece en contextos donde alguien es declarado culpable o expuesto como malhechor. El prefijo intensivo ἐξ- añade fuerza: no se trata de una simple corrección, sino de una refutación completa y pública.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1828', 'spa', 'ser arrastrado, ser apartado; ser halado o seducido fuera de una posición o camino', 'Este verbo significa ser arrastrado o halado fuera, frecuentemente contra la propia resistencia. Santiago 1:14 advierte que cada persona es tentada «cuando de su propia concupiscencia es atraída y seducida». El término sugiere ser apartado de la seguridad hacia el peligro. En el uso clásico incluía arrastrar objetos, rescatar de la esclavitud o tirar de personas heridas. Santiago emplea imágenes de caza y pesca: el deseo pone el cebo y el anzuelo, arrastrando a la víctima desde la rectitud hacia el pecado. La voz pasiva muestra que somos dominados por nuestras propias pasiones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1829', 'spa', 'vómito, materia expulsada del estómago; sustancia arrojada por la boca como imagen de repugnancia moral', 'Este sustantivo poco frecuente designa el vómito o la materia expulsada del estómago por la boca. En 2 Pedro 2:22 se aplica el proverbio «el perro vuelve a su propio vómito» a los falsos maestros que abandonan la fe. El término es gráfico y repulsivo, subrayando la naturaleza asquerosa de la apostasía. Pedro emplea esta imagen visceral para mostrar que regresar a los caminos pecaminosos después de conocer a Cristo resulta tan repugnante como un perro que come su propio vómito. La metáfora enfatiza tanto la contaminación como la degradación voluntaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1830', 'spa', 'escudriñar, examinar cuidadosamente; investigar a fondo o explorar con diligencia', 'Este verbo significa escudriñar o examinar cuidadosamente, realizando una investigación exhaustiva. En 1 Pedro 1:10, los profetas del Antiguo Testamento «escudriñaron diligentemente» acerca de la salvación que ellos mismos profetizaron. El término enfatiza un examen intensivo y meticuloso. El uso clásico y de la LXX muestra que significa investigar a fondo, explorar con rigor. Pedro presenta a los profetas como investigadores diligentes de sus propias profecías, buscando comprender el tiempo y la manera de la salvación venidera que anunciaron pero que no llegaron a entender plenamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1831', 'spa', 'Salir, partir, irse; movimiento físico desde dentro hacia fuera, mandatos imperativos de salir, y extensión figurada de difundirse o emanar.', 'Ἐξέρχομαι es el verbo narrativo por excelencia del Nuevo Testamento para abandonar un espacio cerrado: salir de una casa, partir de una ciudad, emerger de una tumba. Con 219 apariciones cubre prácticamente todo contexto narrativo, desde Jesús saliendo a orar hasta demonios expulsados de sus víctimas. La estructura compuesta (ἐκ + ἔρχομαι, ''fuera de'' + ''ir/venir'') conserva su núcleo espacial incluso en usos extendidos: una noticia ''sale'' por toda la región, palabras ''proceden'' de la boca, y el relámpago ''sale'' del oriente al occidente. El imperativo en contextos de exorcismo resulta especialmente notable, donde el simple mandato de Jesús ''¡Sal!'' porta toda la autoridad del habla divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1832', 'spa', 'Es lícito, está permitido -- verbo impersonal que expresa permisibilidad legal o moral según la Torá o la costumbre.', 'Es lícito, está permitido -- verbo impersonal que expresa permisibilidad legal o moral según la Torá o la costumbre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1833', 'spa', 'examinar detenidamente, indagar, investigar con minuciosidad; interrogar a fondo', 'Este verbo transmite la fuerza de un examen cuidadoso y exhaustivo, no una mirada superficial sino una búsqueda diligente. Cuando se ordena a los magos que «averigüen con diligencia» acerca del niño (Mt 2:8), la palabra capta el interés fingido de Herodes en la precisión. Jesús la emplea al instruir a los setenta que «indaguen» qué casa es digna (Mt 10:11), y Juan la pone en labios de Jesús junto al mar, donde ninguno de los discípulos se atrevió a «preguntarle» quién era (Jn 21:12), una pregunta que habrían investigado a fondo de no haberlo ya reconocido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1834', 'spa', 'Relatar en detalle, explicar, narrar o dar a conocer; ofrecer un recuento completo de hechos o verdades.', 'En el griego clásico este verbo abarcaba desde ''conducir'' hasta ''prescribir'' y ''narrar'', pero en el NT se ha concentrado en el sentido comunicativo de explicar, relatar o dar a conocer algo en detalle. Su uso teológico más significativo aparece en Juan 1:18, donde el Hijo unigénito ''ha dado a conocer'' al Padre invisible, empleando el verbo del cual el español deriva ''exégesis''. En Hechos describe a los misioneros ofreciendo relatos pormenorizados: los discípulos de Emaús explican lo sucedido en el camino (Lucas 24:35), Cornelio refiere su visión (Hechos 10:8), y Pablo y Bernabé narran las señales que Dios obró entre los gentiles (Hechos 15:12, 14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1835', 'spa', 'Sesenta; el número cardinal entre cincuenta y nueve y sesenta y uno.', 'El número cardinal griego indeclinable para sesenta. Aparece en el Nuevo Testamento en contextos agrícolas y geográficos: el rendimiento del sesenta por uno en la parábola del sembrador de Jesús (Mt 13:8, 13:23; Mc 4:8, 4:20), la distancia de sesenta estadios hasta Emaús (Lc 24:13) y medidas simbólicas en Apocalipsis. Su uso en la parábola es especialmente notable: sesenta se sitúa entre treinta y cien como un nivel intermedio de fecundidad, detalle que se conserva idénticamente en el español ''sesenta'', el francés ''soixante'' y el alemán ''sechzig''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1836', 'spa', 'Siguiente, a continuación, sucesivamente; adverbio que marca el tiempo o la secuencia inmediatamente posterior.', 'Adverbio de secuencia temporal o lógica que significa ''a continuación'' o ''al día siguiente''. Lucas y el autor de Hechos prefieren esta palabra para marcar transiciones en el tiempo narrativo: ''al día siguiente'' (Lucas 7:11; 9:37), ''el día siguiente'' tras zarpar (Hechos 21:1; 27:18) y ''al día siguiente'' de un procedimiento legal (Hechos 25:17). Funciona como bisagra narrativa que conduce al lector con fluidez de un episodio al siguiente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1837', 'spa', 'resonar, hacer eco, propagarse como sonido que se extiende ampliamente hacia afuera', 'Este verbo significa resonar o hacer eco hacia afuera, describiendo un sonido que se propaga ampliamente. En 1 Tesalonicenses 1:8, Pablo celebra cómo «de vosotros ha resonado la palabra del Señor» no solo en Macedonia y Acaya, sino en todas partes. El término sugiere resonancia y amplificación. El uso clásico incluía hacer resonar cantos o dar salida a oraciones. Pablo emplea una imagen acústica para ilustrar la difusión evangelística: el evangelio resuena desde Tesalónica como un toque de trompeta, cuyo sonido reverbera mucho más allá de la región inmediata.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1838', 'spa', 'hábito, práctica arraigada, disposición estable; estado consolidado formado mediante la práctica repetida', 'Este sustantivo significa hábito o disposición arraigada, particularmente una formada a través de la práctica constante. En Hebreos 5:14, se habla de creyentes maduros cuyos sentidos están ejercitados «por la práctica» para discernir el bien y el mal. El término denota el estado estable producido por la práctica habitual, en contraste con una condición pasajera. El uso clásico distinguía el hábito fijo del estado cambiante. El autor enfatiza que el discernimiento espiritual no proviene de un aprendizaje puntual, sino de la práctica habituada: músculos morales desarrollados mediante el ejercicio repetido del juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1839', 'spa', 'Estar asombrado o atonito; asombrar a otros; estar fuera de si, perder el juicio. ἐξίστημι literalmente significa desplazar o sacar de posicion, y sus', 'Estar asombrado o atonito; asombrar a otros; estar fuera de si, perder el juicio. ἐξίστημι literalmente significa desplazar o sacar de posicion, y sus usos en el NT trazan un espectro desde el asombro hasta la locura. Con mayor frecuencia aparece en voz media o pasiva intransitiva: las multitudes se asombran por las sanidades de Jesus (Mc 5:42), los maestros quedan atonitos ante la comprension del nino Jesus (Lc 2:47). En su forma activa transitiva, Simon el mago ''asombraba'' a los samaritanos (Hch 8:9-11). El uso mas llamativo es Mc 3:21, donde la propia familia de Jesus declara que esta ''fuera de si'', y 2 Co 5:13, donde Pablo defiende su aparente locura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1840', 'spa', 'ser plenamente capaz, tener fuerza suficiente; poseer la capacidad necesaria para lograr algo', 'Este verbo significa tener plena fuerza o ser completamente capaz de lograr algo. En Efesios 3:18, Pablo ora para que los creyentes «sean capaces de comprender» las dimensiones del amor de Cristo junto con todos los santos. El término enfatiza la fuerza o capacidad suficiente para una tarea. El uso clásico muestra que podía significar prevalecer o tener fuerza bastante. Pablo ora por una capacidad habilitada divinamente: comprender el amor de Cristo requiere más que habilidad humana, necesita el fortalecimiento del Espíritu para abarcar lo que sobrepasa todo conocimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1841', 'spa', 'partida, salida; especialmente el éxodo de la vida o de un lugar de gran significado', 'Este término griego designa una partida o salida, frecuentemente con un peso significativo. En el Evangelio de Lucas describe la muerte venidera de Jesús como su «éxodo» que habría de cumplirse en Jerusalén, vinculando su sacrificio con la liberación fundacional de Israel. El término aparece también en Hebreos en relación con la fe de Moisés respecto al éxodo de Egipto, y en 2 Pedro para referirse a la muerte inminente del apóstol. Así, la palabra porta una carga tanto literal como teológica sobre transiciones trascendentales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1842', 'spa', 'ser completamente destruido, totalmente aniquilado; sufrir destrucción absoluta y definitiva', 'Este verbo significa ser completamente destruido o totalmente eliminado. Hechos 3:23 cita la advertencia de Moisés de que todo aquel que no escuche al profeta «será totalmente destruido de entre el pueblo». El término enfatiza una aniquilación total y definitiva. El uso en la LXX y el NT muestra un lenguaje intensificado de destrucción. Pedro aplica esta advertencia deuteronómica a Cristo: rechazar a Jesús acarrea la exclusión completa del pueblo de Dios. La voz pasiva indica juicio divino: Dios mismo ejecuta esta destrucción total sobre quienes rechazan al Profeta definitivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1843', 'spa', 'Confesar (pecados); alabar o dar gracias (a Dios); consentir o estar de acuerdo (con una propuesta). Verbo compuesto rico (ἐκ + ὁμολογέω) cuyo signifi', 'Confesar (pecados); alabar o dar gracias (a Dios); consentir o estar de acuerdo (con una propuesta). Verbo compuesto rico (ἐκ + ὁμολογέω) cuyo significado gira segun el contexto entre la penitencia, la alabanza y el acuerdo. Su uso mas comun en el NT es confesar pecados, como en el bautismo de Juan donde las multitudes venian ''confesando sus pecados'' (Mt 3:6; Mr 1:5). Sin embargo, en Mt 11:25 y Lc 10:21, Jesus emplea la misma palabra para alabar al Padre, un uso profundamente arraigado en la traduccion de la LXX del hebreo yadah, que de manera similar une confesion y accion de gracias. El ''consentimiento'' de Judas para traicionar a Jesus (Lc 22:6) revela un tercer sentido pragmatico mas raro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1844', 'spa', 'conjurar, poner bajo juramento; exigir solemnemente en el nombre de Dios que alguien diga la verdad', 'Este verbo significa conjurar o poner a alguien bajo juramento solemne, especialmente invocando el nombre de Dios. Mateo 26:63 registra al sumo sacerdote conjurando a Jesús: «Te conjuro por el Dios viviente que nos digas si tú eres el Cristo». El término implica invocar a la deidad como testigo para obligar a una respuesta veraz. En el uso clásico significaba hacer jurar a alguien o exorcizar. El sumo sacerdote emplea la fórmula de juramento más solemne para forzar el testimonio de Jesús, buscando motivos de condena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1845', 'spa', 'exorcistas, los que expulsan demonios; practicantes que echan fuera espíritus malignos mediante fórmulas o rituales', 'Este sustantivo designa a los exorcistas, personas que intentan expulsar demonios o espíritus malignos. Hechos 19:13 describe a exorcistas judíos itinerantes que intentaron invocar el nombre de Jesús sobre los poseídos por espíritus malignos. El término identifica a practicantes profesionales o habituales del exorcismo. Estos individuos empleaban fórmulas y rituales para expulsar demonios, invocando con frecuencia diversos nombres divinos. El relato de Lucas muestra el peligro de usar mecánicamente el nombre de Jesús sin una relación auténtica: los demonios reconocen la impostura y los exorcistas son dominados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1847', 'spa', 'ser tenido por nada, tratado con desprecio; rechazado como indigno o insignificante', 'Este verbo significa ser tenido por nada o tratado con desprecio, ser menospreciado o rechazado. Marcos 9:12 registra a Jesús enseñando que el Hijo del Hombre debe «ser tenido en nada», refiriéndose a su rechazo y sufrimiento venideros. El término enfatiza ser considerado sin valor o insignificante. El uso en la LXX lo emplea para expresar trato despectivo. Jesús profetiza que, a pesar de ser el glorioso Hijo del Hombre de la visión de Daniel, será despreciado y rechazado, siguiendo el camino del Siervo sufriente que Isaías predijo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1848', 'spa', 'Despreciar, tratar con desprecio — considerar a alguien o algo como absolutamente insignificante, rechandolo con desden. El verbo ἐξουθενέω (exouthene', 'Despreciar, tratar con desprecio — considerar a alguien o algo como absolutamente insignificante, rechandolo con desden. El verbo ἐξουθενέω (exoutheneō) expresa un desprecio profundo: tratar a alguien como una nulidad, indigno de toda consideracion. Jesus advierte contra quienes ''despreciaban a los demas'' confiando en su propia justicia (Lc 18:9), y Herodes ''trato a Jesus con desprecio'' en el juicio (Lc 23:11). La piedra rechazada del Salmo 118 es ''tenida por nada'' por los edificadores (Hch 4:11). Pablo insiste en que el fuerte no debe despreciar al debil por cuestiones de dieta y dias santos (Ro 14:3, 10). La palabra conlleva mas fuerza que una simple indiferencia: es un rechazo activo del valor de alguien.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1849', 'spa', 'Autoridad, poder, derecho; capacidad de actuar con fuerza legítima, incluyendo potestades como entidades, jurisdicciones y privilegios concedidos.', 'Ἐξουσία es uno de los términos políticos y teológicos clave del Nuevo Testamento: no designa la fuerza bruta (δύναμις) sino la autoridad sancionada, el derecho de actuar respaldado por legitimidad. Jesús enseña ''con autoridad, no como los escribas'' (Mt 7:29), otorga a sus discípulos autoridad sobre los espíritus inmundos (Mt 10:1) y declara que toda autoridad en el cielo y en la tierra le ha sido dada (Mt 28:18). Pablo extiende el término tanto a las potestades cósmicas como a los gobiernos terrenales (Ro 13:1; Ef 6:12), mientras que Lucas registra su uso para la jurisdicción territorial de Herodes (Lc 23:7). En plural, ''autoridades'' como poderes cósmicos pone a prueba toda tradición de traducción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1850', 'spa', 'Ejercer autoridad o dominio sobre alguien; tener derecho de control; ser dominado por algo', 'Derivado de ἐξουσία (''autoridad, derecho, poder''), este verbo designa el ejercicio activo de autoridad sobre personas o cosas. En Lucas 22:25 Jesús contrasta el modo en que los reyes gentiles ''ejercen dominio'' sobre sus súbditos con el liderazgo de servicio que él propone. Pablo lo emplea de manera memorable en 1 Corintios 6:12, declarando «no me dejaré dominar por nada», usando la voz pasiva para rechazar toda sujeción. En 1 Corintios 7:4, la autoridad mutua de los cónyuges sobre el cuerpo del otro refleja una aplicación notablemente recíproca del término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1851', 'spa', 'prominencia, preeminencia o posición elevada', 'Este término denota prominencia en sentido físico o metafórico. En el uso clásico describía rasgos elevados como figuras en relieve sobre escudos o la naturaleza prominente de los cuernos de animales. Para la época del Nuevo Testamento había desarrollado un sentido metafórico de preeminencia o estatus superior, particularmente en contextos sociales o cívicos. Hechos 25:23 lo emplea para describir la pompa y ceremonia que acompañaba a los altos funcionarios cuando Agripa y Berenice entraron con gran solemnidad ante los oficiales reunidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1852', 'spa', 'despertar del sueño, sacar a alguien del estado de dormir', 'Verbo sencillo que significa despertar a alguien del sueño, derivado del sustantivo ὕπνος (sueño). En voz pasiva indica despertarse de forma natural o ser despertado por otro. En Juan 11:11, Jesús emplea esta palabra como un eufemismo para la muerte al referirse a Lázaro, diciendo «voy para despertarle». La evidencia multilingüe muestra que universalmente se entiende como la acción de sacar a alguien del estado de dormir, ya sea literal o figuradamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G1853', 'spa', 'despierto, que ha sido sacado del sueño (adjetivo)', 'Adjetivo que describe el estado de estar despierto o haber sido sacado del sueño. En Hechos 16:27, el carcelero de Filipos se despierta (ἔξυπνος γενόμενος) y ve las puertas de la prisión abiertas tras el terremoto. La palabra subraya la transición súbita del sueño a la vigilia, frecuentemente con la implicación de alarma o urgencia. Este despertar abrupto lleva al carcelero a desenfundar su espada, suponiendo que los prisioneros han huido.');